/* Enciclopedia — parte 13: frasi mnemoniche, acronimi e trucchi per ricordare (rielaborati; acronimi internazionali spiegati in italiano) */
var MNEMO={
/* ---------- FONDAMENTI ---------- */
"metaparadigma":[["P-A-S-N","I quattro concetti del metaparadigma: Persona, Ambiente, Salute, Nursing. Frase: «Per Andare Sani serve il Nursing»."]],
"teorie-infermieristiche":[["Associa teorica e parola chiave","Nightingale = ambiente; Henderson = 14 bisogni; Orem = self-care (autocura); Peplau = relazione; Roy = adattamento; Leininger = cultura; Watson = caring; Gordon = 11 modelli funzionali. Ripetile come una filastrocca: «ambiente, bisogni, autocura, relazione, adattamento, cultura, caring»."],["In Italia","Marisa Cantarelli = modello delle prestazioni infermieristiche (11 bisogni di assistenza): «Cantarelli canta le prestazioni»."]],
"bisogni-henderson":[["14 bisogni in 4 gruppi","Corpo (respirare, mangiare e bere, eliminare, muoversi, dormire, vestirsi, temperatura, pulizia), sicurezza (evitare i pericoli), relazione (comunicare, culto), realizzazione (lavorare, giocare, imparare). Contare 8 + 1 + 2 + 3 = 14 aiuta a non dimenticarne nessuno."]],
"modelli-gordon":[["11 modelli, un percorso dalla testa ai valori","Si parte dalla percezione della salute, si passa dal corpo (nutrizione, eliminazione, attività, sonno), alla mente (cognitivo-percettivo, percezione di sé), agli altri (ruoli e relazioni, sessualità), allo stress (coping) e si finisce con i valori. Corpo → mente → relazioni → valori."]],
"processo-nursing":[["A-D-P-A-V","Accertamento, Diagnosi, Pianificazione, Attuazione, Valutazione. Frase: «Ad Ogni Paziente Attenzione e Verifica» (ADPAV). È un ciclo: la valutazione riporta all'accertamento."],["Obiettivi SMART","Specifico, Misurabile, Raggiungibile (Achievable), Realistico, Temporizzato: un obiettivo senza «entro quando» non è SMART."]],
"diagnosi-infermieristica":[["PES","Problema (titolo NANDA-I) + Eziologia («correlato a») + Segni e sintomi («evidenziato da»). Trucco: la E sta in mezzo come «correlato», la S chiude con le prove."],["4 tipi","«Problema, Rischio, Promozione, Sindrome»: «PeR Promuovere Salute»."]],
"modello-bifocale":[["Due fuochi","Carpenito: un fuoco sulla diagnosi infermieristica (l'infermiere decide e risponde), l'altro sul problema collaborativo (CP: sorveglia e gestisce con il medico). «CP = Complicanza Potenziale»."]],
"lesioni-pressione":[["Braden = 6 voci","Percezione sensoriale, Umidità, Attività, Mobilità, Nutrizione, Frizione e scivolamento: «Per Una Attenta Mobilizzazione Nutri e Fai attenzione». Punteggio da 6 a 23: più è basso, più alto è il rischio (≤ 18 a rischio)."],["Stadi","Stadio 1 = pelle integra arrossata che non sbianca; 2 = derma scoperto; 3 = grasso visibile; 4 = osso, tendine o muscolo; non stadiabile = fondo coperto da escara o slough."]],
"mobilizzazione":[["Ogni 2 ore","Riposizionamento circa ogni 2 ore (da personalizzare): «due ore, due lati». Semi-Fowler a 30°, decubito laterale a 30°: «30 e 30» per scaricare sacro e trocanteri."]],
"cadute":[["Stratificare e ripetere","Valuta il rischio (es. scala di Conley o Morse) all'ingresso, ad ogni cambiamento clinico e dopo una caduta: «entra, cambia, cade = rivaluta»."]],
"cateterismo":[["Asepsi e sistema chiuso","Il catetere va messo solo se serve e tolto appena possibile: «Indicazione all'ingresso, rimozione al più presto». Sacca sempre sotto il livello della vescica e mai a terra."]],
"disfagia":[["Mento al petto","Postura di sicurezza: seduto a 90° e mento verso il petto durante la deglutizione. Segni di allarme: tosse, voce «gorgogliante», cambiamento della voce dopo il boccone."]],
"igiene-persona":[["Dal pulito allo sporco","Si lava sempre dall'alto verso il basso e dal pulito allo sporco; nella donna la zona genitale dal davanti verso il dietro."]],
/* ---------- RELAZIONE ---------- */
"comunicazione-efficace":[["SBAR","Situazione (che cosa succede), Background (contesto clinico), Assessment (valutazione: che cosa penso), Recommendation (richiesta: che cosa serve). In italiano: «Situazione, Background, Analisi, Richiesta»."],["Read-back","Chi riceve un'informazione critica la ripete: «scrivi, rileggi, conferma»."]],
"teach-back":[["Fammi vedere","«Mi spiega con parole sue come prenderà la pastiglia?» Non «Ha capito?»: si verifica che cosa ha capito la persona, non quanto bene abbiamo parlato noi."]],
"cattive-notizie":[["SPIKES","Setting (luogo e tempo adatti), Perception (che cosa sa già), Invitation (quanto vuole sapere), Knowledge (informare con parole semplici), Emotions (accogliere le emozioni), Strategy and Summary (piano e sintesi)."]],
"aggressivita":[["De-escalation: parla piano, resta vicino all'uscita","Tono calmo, frasi brevi, distanza di sicurezza (almeno un braccio), mai le spalle al muro, via d'uscita libera per entrambi."]],
"burnout":[["Tre E","Esaurimento emotivo, «Estraniamento» (depersonalizzazione, cinismo), Efficacia personale ridotta: le tre dimensioni di Maslach."]],
/* ---------- ETICA ---------- */
"principi-bioetica":[["4 principi: B-N-A-G","Beneficialità, Non maleficenza, Autonomia, Giustizia (Beauchamp e Childress). Frase: «Bene, Non male, Autonomi e Giusti»."]],
"consenso-informato":[["Consenso valido = personale, informato, libero, attuale, revocabile","«PILAR»: Personale, Informato, Libero, Attuale, Revocabile. La legge di riferimento è la L. 219/2017."]],
"dat":[["DAT: io e il futuro; PCC: noi e la malattia","Le DAT (art. 4 L. 219/2017) le scrive la persona per un futuro in cui non potrà decidere; la pianificazione condivisa delle cure (art. 5) si costruisce insieme all'équipe quando una malattia cronica e invalidante peggiora."]],
"segreto-professionale":[["Segreto ≠ privacy","Il segreto riguarda ciò che si sa per la professione (art. 622 c.p.); la privacy riguarda i dati personali (GDPR). «Il segreto si tace, il dato si protegge»."]],
"obiezione-coscienza":[["Obiezione sì, abbandono no","L'obiezione (es. L. 194/1978) non vale per l'assistenza prima e dopo l'intervento né quando la persona è in pericolo di vita."]],
/* ---------- LEGALE ---------- */
"colpa":[["N-I-I","Negligenza (non fare ciò che si deve, disattenzione), Imprudenza (fare ciò che non si deve, avventatezza), Imperizia (non saper fare). «Non fai, fai troppo, non sai fare»."]],
"gelli-bianco":[["24 come le ore del turno di sicurezza","L. 24/2017 (Gelli-Bianco): sicurezza delle cure, linee guida, responsabilità. «24 ore su 24 di sicurezza delle cure». Responsabilità extracontrattuale per il dipendente (5 anni per chiedere i danni, onere della prova al paziente)."]],
"referto-denuncia":[["Referto: 48 ore, subito se pericolo","Il referto (art. 365 c.p.) va presentato entro 48 ore, o subito se c'è pericolo nel ritardo. Lo deve fare chi esercita una professione sanitaria; è escluso se espone l'assistito a procedimento penale. La denuncia (art. 361-362 c.p.) è del pubblico ufficiale o dell'incaricato di pubblico servizio, «senza ritardo»."]],
"cartella-clinica":[["Le qualità della documentazione: CHIARA","Completa, Rintracciabile (chi e quando), Immediata (contemporanea ai fatti), Accurata, Leggibile... e mai cancellare: si corregge con una riga che lascia leggere l'errore, firma e data."]],
"contenzione":[["Ultima, temporanea, documentata","La contenzione è un'eccezione: «ultima risorsa, il minor tempo possibile, prescritta, motivata, documentata e rivalutata spesso»."]],
"tso":[["Tre condizioni insieme","Alterazioni psichiche che richiedono interventi urgenti + rifiuto delle cure + impossibilità di cure extraospedaliere tempestive. Disposto dal sindaco su due certificati medici (proposta e convalida), convalida del giudice tutelare entro 48 ore. «3 condizioni, 2 medici, 1 sindaco, 7 giorni» (durata iniziale)."]],
"accertamento-morte":[["20 minuti di ECG piatto","Morte per arresto cardiaco: registrazione ECG continua di almeno 20 minuti. Morte cerebrale: collegio di tre medici (medico legale, anestesista-rianimatore, neurologo o neurofisiopatologo) e osservazione di almeno 6 ore nell'adulto."]],
/* ---------- ORGANIZZAZIONE ---------- */
"ssn":[["833 = U-U-G","L. 833/1978: Universalità, Uguaglianza, Globalità. Le tre riforme: 833/1978 (nasce il SSN), 502/1992 (aziendalizzazione), 229/1999 (Bindi, razionalizzazione): «nasce, diventa azienda, si razionalizza»."]],
"lea":[["Tre macro-livelli","Prevenzione collettiva e sanità pubblica, assistenza distrettuale, assistenza ospedaliera: «Prevenire, Territorio, Ospedale»."]],
"dm77":[["Numeri del territorio","Casa della comunità hub ogni 40-50.000 abitanti; IFeC 1 ogni 3.000 abitanti; Ospedale di comunità 20 posti letto ogni 100.000; COT 1 ogni 100.000; distretto circa 100.000. Trucco: «tre mila per l'infermiere, centomila per la centrale»."]],
"ifec":[["1 ogni 3.000","Un infermiere di famiglia e comunità ogni 3.000 abitanti (DM 77/2022): «tre zeri, una famiglia»."]],
"consegne":[["I-PASS","Illness severity (gravità), Patient summary (sintesi), Action list (cose da fare), Situation awareness (che cosa può cambiare e come reagire), Synthesis by receiver (chi riceve riassume). In alternativa usa SBAR."]],
"rischio-clinico":[["Modello del formaggio svizzero","Reason: l'errore passa quando i buchi di più fette (difese) si allineano. Errori attivi (persona) + condizioni latenti (organizzazione)."],["Strumenti: prima e dopo","Prima dell'evento (proattivi): FMEA. Dopo l'evento (reattivi): root cause analysis, audit, incident reporting. «FMEA prevede, RCA ricostruisce»."]],
"qualita":[["Ciclo PDCA","Plan, Do, Check, Act (Deming): pianifica, fai, verifica, agisci. È una ruota che non si ferma."]],
"privacy":[["2016 nasce, 2018 si applica","GDPR = Reg. UE 2016/679, applicato dal 25 maggio 2018; in Italia il D.Lgs. 196/2003 è stato adeguato dal D.Lgs. 101/2018."]],
"ecm":[["150 crediti in 3 anni","Obbligo formativo ECM: 150 crediti nel triennio (con eventuali riduzioni). «Centocinquanta in tre»."]],
/* ---------- IGIENE ---------- */
"igiene-mani":[["5 momenti OMS","Prima del contatto con il paziente; prima di una manovra asettica; dopo esposizione a liquidi biologici; dopo il contatto con il paziente; dopo il contatto con l'ambiente del paziente. Frase: «PRIMA tocco e asepsi, DOPO liquidi, paziente e ambiente» (2 prima, 3 dopo)."],["Tempi","Frizione alcolica 20-30 secondi; lavaggio con acqua e sapone 40-60 secondi. Con Clostridioides difficile si usano acqua e sapone (l'alcol non uccide le spore)."]],
"precauzioni":[["Contatto, droplet, aerea: distanza crescente","Contatto = toccare (guanti e camice, es. MRSA, C. difficile, scabbia). Droplet = goccioline entro circa 1 metro (mascherina chirurgica, es. influenza, meningococco, pertosse). Aerea = particelle che restano sospese (FFP2/FFP3 e stanza a pressione negativa: «M-V-T» Morbillo, Varicella, Tubercolosi)."],["Vestizione e svestizione","Si indossa: camice, mascherina, occhiali, guanti. Si toglie: guanti, occhiali, camice, mascherina (la parte più contaminata per prima, la protezione delle vie aeree per ultima, fuori dalla stanza)."]],
"sterilizzazione":[["Spaulding: critico, semicritico, non critico","Critico (entra in tessuti sterili) → sterilizzazione; semicritico (mucose) → disinfezione di alto livello; non critico (cute integra) → detersione o disinfezione di basso livello. «Taglia, tocca dentro, tocca fuori»."],["Prima si pulisce","Sequenza: decontaminazione, lavaggio, asciugatura, confezionamento, sterilizzazione: senza pulizia la sterilizzazione non funziona."]],
"esposizione-biologica":[["Lava, non spremere, segnala","Far sanguinare spontaneamente, lavare con acqua e sapone, disinfettare, segnalare subito. Regola del 3 nel rischio di trasmissione: HBV fino a circa 30% (non vaccinati), HCV circa 2-3%, HIV circa 0,3% per puntura con ago contaminato: «30, 3, 0,3»."]],
"rifiuti-sanitari":[["DPR 254/2003","Rifiuti sanitari pericolosi a rischio infettivo: contenitori rigidi per taglienti, riempiti non oltre i 3/4, mai reincappucciare gli aghi."]],
"vaccinazioni":[["Vivi attenuati: MPRV + febbre gialla","Morbillo, Parotite, Rosolia, Varicella sono vaccini vivi: non in gravidanza e nei gravemente immunodepressi. «MPRV non va in pancia»."]],
"prevenzione":[["Primaria, secondaria, terziaria","Primaria = evitare che la malattia nasca (vaccini, stili di vita); secondaria = scoprirla presto (screening); terziaria = limitare danni e recidive (riabilitazione). «Prima non viene, poi si scopre, infine si limita»."]],
/* ---------- RICERCA ---------- */
"ebn":[["PICO","Paziente/Popolazione, Intervento, Confronto, Outcome (esito): la domanda clinica ben fatta."],["5 A","Ask (chiedi), Acquire (cerca), Appraise (valuta criticamente), Apply (applica), Assess (verifica il risultato)."]],
"livelli-evidenza":[["Piramide dal basso","Opinione dell'esperto → serie di casi → caso-controllo → coorte → RCT → revisioni sistematiche e metanalisi in cima."]],
"statistica":[["Sensibilità: SnNout; specificità: SpPin","Un test molto Sensibile, se Negativo, esclude (rule out); un test molto Specifico, se Positivo, conferma (rule in)."]],
/* ---------- ANATOMIA ---------- */
"cuore-fisiologia":[["Valvole: «Tutti Polmoni Muovono Aria»","Tricuspide, (atrio→ventricolo destro), Polmonare, Mitrale, Aortica: il percorso del sangue nel cuore destro e sinistro."],["Gittata cardiaca","GC = FC × gittata sistolica (circa 70 ml × 70 battiti ≈ 5 litri al minuto). PAM ≈ (PAS + 2 × PAD) / 3."]],
"respiro-fisiologia":[["La CO2 comanda il respiro","Lo stimolo principale a respirare è la CO2 (pH del liquor); nel BPCO con ipercapnia cronica conta di più l'ipossiemia: per questo l'ossigeno si titola (88-92%)."]],
"rene-fisiologia":[["Le funzioni del rene: «A WET BED»","Acido-base, Water (acqua), Elettroliti, Tossine, Blood pressure (pressione, renina), Eritropoietina, D (vitamina D attiva)."]],
"sistema-nervoso":[["Nervi cranici","I olfattivo, II ottico, III oculomotore, IV trocleare, V trigemino, VI abducente, VII faciale, VIII vestibolococleare, IX glossofaringeo, X vago, XI accessorio, XII ipoglosso. Frase classica inglese con le stesse iniziali: «Oh Oh Oh To Touch And Feel Very Good Velvet, Ah Heaven» (Olfattivo, Ottico, Oculomotore, Trocleare, Trigemino, Abducente, Faciale, Vestibolococleare, Glossofaringeo, Vago, Accessorio, Hypoglosso)."]],
"cute":[["Lesioni elementari: piatte, rilevate, con liquido","Piatte: macula. Rilevate e solide: papula (< 1 cm), nodulo (> 1 cm), pomfo (orticaria). Con liquido: vescicola (< 1 cm), bolla (> 1 cm), pustola (pus)."]],
"sangue":[["Donatore e ricevente","Globuli rossi: 0 negativo dona a tutti, AB positivo riceve da tutti. Plasma: al contrario, AB è il donatore universale. «I globuli dallo zero, il plasma dall'AB»."]],
/* ---------- FARMACOLOGIA ---------- */
"regole-somministrazione":[["Regola delle 7 G","Giusto farmaco, Giusta dose, Giusta via, Giusto orario, Giusto paziente, Giusta registrazione, Giusto controllo (o giusto approccio al paziente, a seconda del testo). Nasce dalle «5 G» (paziente, farmaco, dose, via, orario) e alcuni testi arrivano a 10, aggiungendo informazione, diritto di rifiutare e rivalutazione. Trucco: le prime 5 sono le «G del carrello» (si controllano prima di somministrare), le ultime 2 le «G della penna» (si fanno dopo)."],["Tre controlli","Si confronta il farmaco con la prescrizione tre volte: quando lo prendi, quando lo prepari, prima di somministrarlo al letto."],["Identificazione","Almeno due identificativi (nome e cognome, data di nascita), mai il numero del letto; domanda aperta: «Come si chiama?» e non «Lei è il signor Rossi?»."]],
"vie-somministrazione":[["Angoli delle iniezioni","Intradermica 10-15°, sottocutanea 45° (90° con ago corto o pizzicotto abbondante), intramuscolare 90°: «15, 45, 90»."],["Z-track","Nell'intramuscolo di farmaci irritanti si sposta la cute di lato prima di pungere: il tragitto a zeta impedisce al farmaco di risalire."]],
"calcolo-dosaggi":[["Quello che vuoi su quello che hai","Volume = (dose prescritta ÷ dose disponibile) × volume della confezione. «Voglio diviso Ho, per il Volume»."],["Gocce","Deflussore standard: 20 gocce = 1 ml; microgocciolatore: 60 microgocce = 1 ml. ml/ora ÷ 3 = gocce/minuto (con 20 gtt/ml): «500 ml in 8 ore ≈ 62 ml/h ≈ 21 gocce/min»."]],
"sicurezza-farmaci":[["LASA = Look-Alike Sound-Alike","Farmaci che si somigliano nel nome o nella confezione: separarli, evidenziarli e leggere sempre due volte. Tall Man Lettering: parti diverse del nome in maiuscolo (es. «idrOSSIzina / idrALAzina»)."],["Farmaci ad alto rischio: A PINCH","Antimicrobici (alcuni), Potassio e altri elettroliti concentrati, Insulina, Narcotici (oppioidi), Chemioterapici, Heparin (eparina e altri anticoagulanti)."]],
"stupefacenti":[["Registro: subito, senza cancellature, 2 anni","Ogni carico e scarico si registra subito, senza abrasioni (le correzioni restano leggibili); il registro si conserva 2 anni dall'ultima registrazione."]],
"oppioidi":[["Triade dell'intossicazione: coma, miosi, bradipnea","«Dorme, pupille a spillo, respira poco»: si sostiene il respiro e si dà naloxone (dura meno dell'oppioide: sorvegliare la ricaduta)."],["Sedazione prima del respiro","La sonnolenza compare prima della depressione respiratoria: valuta il livello di sedazione prima di ogni dose."]],
"anticoagulanti":[["Eparina = aPTT, Warfarin = INR","«Eparina è PTT con una lettera in più (aPTT); Warfarin e INR hanno una W e una I che vanno a braccetto». Antidoti: eparina → protamina («la P per la P»); warfarin → vitamina K (K come la vitamina del sangue che coagula)."],["Eparina sottocute","Addome, a 5 cm dall'ombelico, senza aspirare e senza massaggiare; la bolla d'aria nelle siringhe pre-riempite non si espelle."]],
"insuline":[["Rapida, intermedia, lenta","Rapida: inizio in 10-15 minuti, ai pasti; lenta (basale): circa 24 ore senza picco, una volta al giorno. «Rapida = pasto, basale = base»."],["Mai la basale insieme alla rapida per errore","Penne di colore diverso; sempre controllare il nome prima: la basale non si «corregge» al bisogno."]],
"antibiotici":[["Emocolture prima, antibiotico entro l'ora","Nella sepsi: «colture prima se non ritardano, antibiotico entro 60 minuti»."],["Vancomicina: red man (sindrome dell'uomo rosso)","Arrossamento di volto e collo se infusa troppo in fretta: si rallenta l'infusione (almeno 60 minuti)."]],
"diuretici":[["Furosemide perde K, spironolattone lo trattiene","«Ansa e tiazidi = Kalo del potassio; Risparmiatori = Ritengono il potassio»."]],
"digossina":[["Conta il polso prima","Frequenza apicale per 1 minuto: sotto 60 non somministrare e avvisare. Segni di tossicità: nausea, vista gialla-verde, bradicardia: «vede giallo e va piano». L'ipopotassiemia la rende più tossica."]],
"antidoti":[["Coppie da ricordare","Oppioidi → naloxone; benzodiazepine → flumazenil; paracetamolo → N-acetilcisteina; eparina → protamina; warfarin → vitamina K; dabigatran → idarucizumab; insulina/ipoglicemia → glucosio o glucagone; digossina → anticorpi antidigossina; organofosfati → atropina; magnesio solfato → calcio gluconato; metanolo → fomepizolo o etanolo; CO → ossigeno."]],
"interazioni":[["Il pompelmo blocca","Il succo di pompelmo inibisce il CYP3A4: aumentano i livelli di molti farmaci (alcune statine, calcioantagonisti). Il latte e il calcio legano tetracicline, chinoloni, ferro e levotiroxina."]],
"riconciliazione":[["Tre momenti di passaggio","Ricognizione e riconciliazione a ogni transizione: ingresso, trasferimento, dimissione (Raccomandazione 17). «Entra, si sposta, esce = riconcilia»."]],
"trasfusione":[["I primi 15 minuti","Si trasfonde lentamente per i primi 15 minuti restando vicino al paziente: le reazioni gravi compaiono subito. Parametri prima, dopo 15 minuti e alla fine."],["Mai con altro","Nella linea della trasfusione solo fisiologica: niente glucosata (emolisi) né farmaci."],["Reazioni: TACO e TRALI","TACO = sovraccarico (ipertensione, edema, risponde al diuretico); TRALI = danno polmonare (ipotensione, febbre, non risponde al diuretico). «TACO è troppo, TRALI è tossico»."]],
"farmacovigilanza":[["Segnala sempre il sospetto","Non serve la certezza: si segnala anche il semplice sospetto di reazione avversa, entro 2 giorni (36 ore per i farmaci biologici) tramite la Rete nazionale di farmacovigilanza."]],
/* ---------- ECG ---------- */
"ecg-basi":[["Elettrodi periferici: «Rosso a destra, Giallo a sinistra, Verde sul cuore... e il Nero per terra»","Sistema europeo: rosso braccio destro, giallo braccio sinistro, verde gamba sinistra, nero gamba destra (terra). Trucco del semaforo che gira in senso orario: rosso → giallo → verde."],["Precordiali","V1 e V2: 4° spazio intercostale a destra e a sinistra dello sterno; V4: 5° spazio sull'emiclaveare; V3 a metà tra V2 e V4; V5 ascellare anteriore e V6 ascellare media allo stesso livello di V4."],["Carta","Quadretto piccolo = 0,04 s; quadrato grande = 0,20 s; 5 quadrati grandi = 1 secondo. FC = 300 ÷ numero di quadrati grandi tra due R."]],
"ecg-lettura":[["Metodo in 5 passi","Frequenza, Ritmo, onde P, PR, QRS (poi ST e T): «Frequenza Ritmo Prima, Poi Quadra»."],["Numeri chiave","PR 0,12-0,20 s (3-5 quadretti); QRS < 0,12 s (meno di 3 quadretti); QTc < 450 ms nell'uomo, < 460-470 nella donna."]],
"ritmi":[["Defibrillabili: «FV e TV senza polso»","Gli unici ritmi di arresto da defibrillare sono fibrillazione ventricolare e tachicardia ventricolare senza polso; asistolia e PEA non si defibrillano."]],
"blocchi-av":[["La poesia dei blocchi","1° grado: «PR lungo, ma tutte passano». 2° tipo 1 (Wenckebach): «più lungo, più lungo, più lungo, salta: ecco il Wenckebach». 2° tipo 2 (Mobitz II): «PR fisso, poi una P non passa». 3° grado: «P e QRS non si parlano: ognuno per conto suo»."]],
"stemi":[["Derivazioni e territori","Inferiore: II, III, aVF (coronaria destra). Anteriore: V1-V4 (discendente anteriore). Laterale: I, aVL, V5-V6 (circonflessa). «Due-tre-F guardano giù»."]],
"elettroliti-ecg":[["Potassio alto: T a tenda","«Il potassio alto pianta la tenda»: T alte e appuntite, poi PR lungo, P che scompare, QRS largo, onda sinusoidale. Potassio basso: T piatte e onde U («U come giù»)."],["Calcio","Calcio alto = QT corto; calcio basso = QT lungo: «il calcio allunga se manca»."]],
"ecg-blocchi-branca":[["William e Marrow","Branca sinistra: V1 a W, V6 a M → «WiLLiaM» (W-L-M). Branca destra: V1 a M, V6 a W → «MaRRoW» (M-R-W)."]],
"ecg-pericardite":[["Sorriso diffuso","Sopraslivellamento ST diffuso a «sella» (concavo, un sorriso) in molte derivazioni e sottoslivellamento del PR; nell'infarto l'ST è spesso convesso («triste») e localizzato."]],
"ecg-torsione":[["Torsione = magnesio","La torsione di punta si tratta con magnesio solfato; si cercano i farmaci che allungano il QT. «La torsione si sbroglia con il magnesio»."]],
"ecg-preeccitazione":[["WPW: PR corto, onda delta, QRS largo","«Corto, delta, largo». In fibrillazione atriale con WPW evitare i farmaci che bloccano il nodo AV (adenosina, beta-bloccanti, calcioantagonisti, digossina)."]],
"ecg-ipotermia":[["Onda J di Osborn","Gobba alla fine del QRS: «Osborn ha freddo». Con ipotermia profonda la defibrillazione è meno efficace finché il paziente non si riscalda."]],
"ecg-pacemaker":[["Codice a lettere: chi, chi, come","1ª lettera = camera stimolata, 2ª = camera sentita, 3ª = risposta (I inibisce, T triggera, D duale). VVI = stimola il ventricolo, sente il ventricolo, si inibisce se c'è un battito proprio."]],
/* ---------- EMERGENZA ---------- */
"parametri-vitali":[["NEWS2: 7 parametri","Frequenza respiratoria, SpO2, ossigeno sì/no, PA sistolica, frequenza cardiaca, coscienza (ACVPU), temperatura. Allerta: 5-6 o 3 in un solo parametro = risposta urgente; ≥ 7 = emergenza."]],
"abcde":[["ABCDE","Airway (vie aeree), Breathing (respiro), Circulation (circolo), Disability (stato neurologico), Exposure (esposizione ed esame testa-piedi). Regola d'oro: si tratta ciò che si trova prima di passare alla lettera dopo."],["AVPU / ACVPU","Alert (vigile), Confusion (nuova confusione), Voice (risponde alla voce), Pain (risponde al dolore), Unresponsive (non risponde)."],["SAMPLE per l'anamnesi","Sintomi, Allergie, Medicinali, Precedenti (storia clinica), Last meal (ultimo pasto), Eventi che hanno portato al problema."]],
"triage":[["Cinque codici numerici","1 rosso (emergenza, accesso immediato), 2 arancione (urgenza, entro 15 minuti), 3 azzurro (urgenza differibile, entro 60), 4 verde (minore, entro 120), 5 bianco (non urgenza, entro 240): «0, 15, 60, 120, 240»."]],
"maxiemergenza":[["START: 30-2-può fare","Cammina → verde. Respiro > 30 → rosso. Riempimento capillare > 2 secondi (o polso radiale assente) → rosso. Non esegue ordini semplici → rosso. Altrimenti giallo. «30-2-può fare» (respiro, refill, ordini)."]],
"bls-acls":[["30:2, 100-120, 5-6","Compressioni:ventilazioni 30:2 nell'adulto; frequenza 100-120 al minuto; profondità 5-6 cm; cambio di chi comprime ogni 2 minuti."],["Cause reversibili: 4 H e 4 T","Ipossia, Ipovolemia, Ipo/iperkaliemia (e altri disturbi metabolici), Ipotermia; Trombosi (coronarica o polmonare), Tamponamento cardiaco, Tossici, Tensione (pneumotorace iperteso)."],["Adrenalina","Ritmo non defibrillabile: adrenalina 1 mg subito, poi ogni 3-5 minuti. Defibrillabile: dopo il 3° shock adrenalina 1 mg e amiodarone 300 mg; amiodarone 150 mg dopo il 5°."]],
"ostruzione-vie-aeree":[["5 + 5","Ostruzione grave nel cosciente: 5 colpi interscapolari, poi 5 compressioni addominali (manovra di Heimlich), alternando. Se perde coscienza: RCP."]],
"shock":[["Quattro tipi: «I Cuori Ostruiti Distribuiscono»","Ipovolemico, Cardiogeno, Ostruttivo (embolia, tamponamento, pneumotorace iperteso), Distributivo (settico, anafilattico, neurogeno)."],["Shock index","FC ÷ PA sistolica: oltre 1 è segno di allarme («il cuore supera la pressione»)."]],
"sepsi":[["qSOFA = 2 su 3","Frequenza respiratoria ≥ 22, alterazione dello stato mentale, PA sistolica ≤ 100: «22-mente-100»."],["Sepsis Six (entro un'ora): 3 dentro, 3 fuori","Dentro: ossigeno, antibiotico, liquidi. Fuori: emocolture, lattati, diuresi oraria."]],
"anafilassi":[["Adrenalina intramuscolo nella coscia","0,5 mg (0,5 ml di 1 mg/ml) nell'adulto, nella faccia anterolaterale della coscia, ripetibile dopo 5 minuti. «Mezzo milligrammo, mezza coscia, ogni cinque minuti»."]],
"trauma":[["xABCDE","La x sta per le emorragie massive esterne: prima si ferma il sangue (compressione, laccio), poi le vie aeree con protezione del rachide cervicale."],["Triade letale","Ipotermia, acidosi, coagulopatia: «freddo, acido, sanguina»."]],
"trauma-cranico":[["Triade di Cushing","Ipertensione (con differenziale aumentata), bradicardia, respiro irregolare: segno tardivo di ipertensione endocranica. «Pressione su, cuore giù, respiro strano»."]],
"glasgow":[["4-5-6","Occhi massimo 4, Verbale massimo 5, Motorio massimo 6: totale da 3 a 15. I numeri salgono nello stesso ordine delle lettere O-V-M («Ogni Visita Medica»: 4-5-6). GCS ≤ 8 = «otto, intubo»."]],
"ustioni":[["Regola del 9 di Wallace","Testa 9%, ciascun arto superiore 9%, ogni arto inferiore 18%, tronco anteriore 18%, tronco posteriore 18%, genitali 1%. Il palmo della mano della persona (con le dita) vale circa 1%."],["Raffreddare","Acqua corrente fresca (non ghiacciata) per circa 20 minuti; poi coprire e prevenire l'ipotermia."]],
"intossicazioni":[["Colinergico: SLUDGE","Salivazione, Lacrimazione, Urinazione, Defecazione, disturbi Gastrointestinali, Emesi (più miosi e bradicardia): organofosfati, alcuni funghi."],["Anticolinergico: «Secco come un osso, rosso come una barbabietola, caldo come una lepre, cieco come un pipistrello, matto come un cappellaio»","Cute secca, arrossata, ipertermia, midriasi, delirio (atropina, antistaminici, triciclici)."]],
"emogasanalisi":[["ROME","Respiratory Opposite, Metabolic Equal: nel disturbo respiratorio pH e pCO2 vanno in direzioni opposte; nel metabolico pH e HCO3- vanno nella stessa direzione."],["Ordine di lettura","pH → pCO2 → HCO3- → compenso → ossigenazione (P/F)."],["MUDPILES","Cause di acidosi metabolica a gap aumentato: Metanolo, Uremia, Diabete (chetoacidosi), Paraldeide/Propilenglicole, Isoniazide/Iron (ferro), Lattati, Etilenglicole, Salicilati."]],
"ossigenoterapia":[["Target: 94-98, nei BPCO 88-92","«Tutti 94, chi trattiene CO2 si ferma a 88»."],["Dispositivi in ordine di FiO2","Occhialini (1-6 l/min, circa 24-44%), maschera semplice (5-10 l/min), Venturi (FiO2 fissa), maschera con reservoir (10-15 l/min, fino a circa 80-90%)."]],
"ventilazione":[["DOPE: il ventilato peggiora","Displacement (tubo dislocato), Obstruction (tubo ostruito), Pneumothorax (pneumotorace), Equipment (guasto dell'apparecchio)."]],
"cvc":[["Bundle di inserimento","Igiene delle mani, barriere massime, clorexidina al 2% in alcol, evitare la femorale, rimuovere appena non serve."],["Scrub the hub","Disinfetta il raccordo strofinando per almeno 15 secondi prima di ogni accesso."]],
/* ---------- MEDICINA ---------- */
"sca":[["MONA non è più la regola","Vecchio acronimo Morfina, Ossigeno, Nitrati, Aspirina: oggi l'ossigeno si dà solo se SpO2 < 90%, la morfina con cautela. Resta valido ricordare: ECG entro 10 minuti dall'arrivo."],["STEMI: tempo è muscolo","Riperfusione con angioplastica primaria entro 120 minuti dalla diagnosi."]],
"dolore-toracico":[["PQRST del dolore","Provocazione/palliazione, Qualità, Regione e irradiazione, Severità (NRS), Tempo (inizio, durata)."],["Le cinque cause che uccidono","Infarto, dissezione aortica, embolia polmonare, pneumotorace iperteso, tamponamento cardiaco (più rottura esofagea): «IDEPT»."]],
"scompenso":[["Sinistro = polmone, destro = periferia","Scompenso sinistro: dispnea, ortopnea, crepitii («congestione a monte del cuore sinistro = polmoni»). Destro: edemi declivi, turgore giugulare, epatomegalia."],["Peso: 2 kg in 3 giorni","Aumento di 1-2 kg in 2-3 giorni = avvisare: «due chili, tre giorni, telefona»."]],
"ipertensione":[["Misurazione corretta: 3-2-1","Seduto da almeno 3-5 minuti, 2 misurazioni a distanza di 1-2 minuti, bracciale all'altezza del cuore e di misura giusta."]],
"fibrillazione-atriale":[["CHA2DS2-VASc","Cardiac failure (scompenso) 1, Hypertension 1, Age ≥ 75 2, Diabete 1, Stroke/TIA 2, Vascular disease 1, Age 65-74 1, Sex category (femmina) 1: stima il rischio di ictus per decidere l'anticoagulazione."],["Irregolarmente irregolare","Niente P, R-R completamente irregolari: «nessuna P, nessuna regola»."]],
"tev":[["Triade di Virchow","Stasi, danno della parete del vaso, ipercoagulabilità: «Stasi, Lesione, Coagulo»."]],
"bpco":[["Pink puffer e blue bloater","Enfisematoso «soffiatore rosa» (magro, dispnoico, labbra socchiuse); bronchitico «gonfio blu» (cianotico, edematoso). Immagini vecchie ma utili."],["Respirazione a labbra socchiuse","«Annusa il fiore, spegni la candela»: inspira dal naso, espira lentamente dalla bocca socchiusa."]],
"asma":[["Il torace silente spaventa","Nell'asma grave il silenzio respiratorio e una pCO2 normale o alta sono segni di esaurimento: «se non fischia più, non è un buon segno»."],["Distanziatore","Spray dosato con distanziatore: agita, 1 spruzzo, 5-10 respiri lenti (o trattenere il respiro 10 secondi). Dopo il corticosteroide inalatorio sciacquare la bocca."]],
"diabete":[["Le 3 P","Poliuria, Polidipsia, Polifagia (più calo di peso nel tipo 1)."],["Rotazione dei siti","Ruotare i siti di iniezione per evitare la lipodistrofia: «cambia casella ogni volta» (dividere l'addome in quadranti)."]],
"ipoglicemia":[["Regola del 15","15 g di zuccheri semplici, ricontrolla dopo 15 minuti, ripeti se ancora < 70 mg/dl; poi uno spuntino."],["Freddo e sudato, dagli lo zucchero","Cute fredda e sudata = ipoglicemia; cute calda e secca = iperglicemia: «freddo e sudato, zucchero dato»."]],
"chetoacidosi":[["Respiro di Kussmaul e alito di frutta","Respiro profondo e frequente per eliminare CO2, alito fruttato (acetone). Con l'insulina il potassio scende: «insulina giù il K, controllalo»."]],
"piede-diabetico":[["Ispeziona ogni giorno","Controllo quotidiano dei piedi (anche con uno specchio), mai camminare scalzi, tagliare le unghie dritte, scarpe comode, niente borse dell'acqua calda."]],
"tiroide":[["Iper accelera, ipo rallenta","Ipertiroidismo: tutto veloce (tachicardia, diarrea, calo di peso, caldo). Ipotiroidismo: tutto lento (bradicardia, stipsi, aumento di peso, freddo)."]],
"ictus":[["BE-FAST","Balance (equilibrio), Eyes (vista), Face (bocca storta), Arm (braccio che cade), Speech (parola), Time (ora d'inizio, chiama il 118). Il tempo di esordio decide la trombolisi."],["Cincinnati: 3 segni","Faccia, braccio, linguaggio: basta uno alterato per sospettare l'ictus."]],
"epilessia":[["Proteggi, non trattenere","Durante la crisi: proteggere la testa, niente in bocca, non bloccare i movimenti, cronometrare; dopo, posizione laterale di sicurezza. Oltre 5 minuti = stato di male: farmaco di emergenza."]],
"insufficienza-renale":[["Prerenale, renale, postrenale","«Prima, dentro, dopo»: prima del rene (poco sangue), dentro il rene (danno del tessuto), dopo il rene (ostruzione)."],["KDIGO in tre numeri","+0,3 mg/dl in 48 ore, 1,5 volte in 7 giorni, < 0,5 ml/kg/ora per 6 ore."]],
"elettroliti":[["Sodio: lento a correggere","Correzione dell'iponatriemia cronica non oltre 8-10 mmol/l al giorno: «dal basso all'alto, lento è salvo» (rischio di demielinizzazione osmotica)."],["KCl: mai in bolo","«Il potassio va in flebo, mai in vena diretta» (Raccomandazione n. 1)."]],
"bilancio-idrico":[["Entrate meno uscite","Entrate: bevande, alimenti, infusioni, nutrizione, acqua metabolica. Uscite: urine, feci, drenaggi, vomito, perspiratio (circa 500-800 ml al giorno, di più con la febbre). 1 kg di peso ≈ 1 litro di liquidi."]],
"epatopatie":[["Child-Pugh: «ABC + EA»","Albumina, Bilirubina, Coagulazione (INR), Encefalopatia, Ascite: cinque voci per la gravità della cirrosi."]],
"emorragia-digestiva":[["Alta e bassa","Ematemesi e melena (feci nere, picee) → sopra il legamento di Treitz; ematochezia (sangue rosso dall'ano) → di solito bassa. «Nero viene dall'alto»."]],
"mici":[["Crohn salta, rettocolite continua","Crohn: dalla bocca all'ano, a salti, tutta la parete. Rettocolite ulcerosa: parte dal retto e risale senza interruzioni, solo la mucosa."]],
/* ---------- CHIRURGIA ---------- */
"preoperatorio":[["Digiuno 6-2","Cibi solidi fino a 6 ore prima, liquidi chiari fino a 2 ore prima (latte materno 4 ore nei lattanti): «6 per mangiare, 2 per bere»."]],
"checklist-chirurgica":[["Tre tempi: Sign in, Time out, Sign out","Prima dell'induzione, prima dell'incisione, prima dell'uscita dalla sala (Raccomandazione n. 2 e checklist OMS): «entra, ferma tutto, esci»."],["Conta delle garze","Conteggio di garze, strumenti e aghi all'inizio, alla chiusura di cavità e alla fine."]],
"anestesia":[["Aldrete per uscire dalla recovery","Attività, respiro, circolo, coscienza, colore (o saturazione): ognuno 0-2, dimissibile con ≥ 9."]],
"postoperatorio":[["Le 5 W della febbre postoperatoria","Wind (polmone, primi giorni), Water (urine, 3°-5° giorno), Wound (ferita, 5°-7°), Walking (trombosi venosa), Wonder drugs (farmaci) — «vento, acqua, ferita, cammino, farmaci»."]],
"ferita-chirurgica":[["Non toccare per 48 ore","La medicazione chirurgica pulita si lascia in sede circa 48 ore se asciutta: la ferita si sigilla."]],
"drenaggi":[["Sotto, chiuso, osservato","Contenitore sempre sotto il livello di inserzione, sistema chiuso, annotare quantità e aspetto: «giù, chiuso, scritto»."]],
"pneumotorace":[["Iperteso: trachea dall'altra parte","Dispnea grave, ipotensione, turgore giugulare, assenza di murmure, trachea deviata dal lato opposto: si decomprime subito, non si aspetta la radiografia."],["Drenaggio toracico","Gorgoglio continuo nella camera ad acqua = perdita d'aria; oscillazione del livello con il respiro = drenaggio pervio. Non clampare di routine."]],
"addome-acuto":[["Segni da ricordare","Blumberg (dolore al rilascio = peritonite), Murphy (stop inspiratorio = colecisti), McBurney (punto dell'appendice), Giordano (colpo sulla loggia renale)."]],
"occlusione":[["4 segni","Dolore crampiforme, vomito, distensione, chiusura dell'alvo a feci e gas: «dolore, vomito, gonfio, chiuso»."]],
"sng":[["NEX","Misura Naso-Earlobe-Xiphoid: dalla punta del naso al lobo dell'orecchio e poi al processo xifoideo. Posizione confermata con radiografia (o pH dell'aspirato ≤ 5,5), mai con l'insufflazione d'aria."]],
"stomie":[["Colore: rosso è sano","Lo stoma sano è rosso-rosa e umido; scuro o nero = ischemia (avvisare). Il foro della placca si ritaglia 2-3 mm più grande dello stoma."]],
"tracheostomia":[["Al letto: tre cose","Cannula di riserva della stessa misura, una più piccola, aspiratore e ossigeno pronti: «riserva, più piccola, aspira»."],["Aspirazione","Non oltre 10-15 secondi per passaggio, preossigenare, aspirare solo in risalita."]],
"ortopedia":[["Sindrome compartimentale: le 6 P","Pain (dolore sproporzionato, il primo segno), Pallor, Paresthesia, Paralysis, Pulselessness (tardivo), Poikilothermia (arto freddo)."],["Distorsione: RICE","Rest (riposo), Ice (ghiaccio), Compression (compressione), Elevation (sollevamento)."]],
"ulcere-arti":[["Venosa o arteriosa","Venosa: malleolo interno, bordi irregolari, essudato, migliora sollevando la gamba → compressione. Arteriosa: dita e piede, bordi netti, pallida, dolorosa, peggiora sollevando → niente compressione prima dell'indice caviglia-braccio. «Venosa su, arteriosa giù»."]],
"medicazioni-avanzate":[["TIME","Tissue (tessuto non vitale), Infection/Inflammation, Moisture (umidità), Edge (bordi): i quattro punti per preparare il letto della ferita."]],
/* ---------- INFETTIVE ---------- */
"tbc":[["Tre campioni di escreato","Escreato per 3 giorni, preferibilmente al mattino; isolamento aereo con FFP2 per gli operatori e mascherina chirurgica per il paziente quando esce dalla stanza."]],
"epatiti":[["Le vocali vanno con le... vie","A ed E vanno per bocca (oro-fecale, «A ed E come Alimenti»); B, C e D per sangue e liquidi biologici."]],
"hiv":[["Finestra e PEP","PEP (profilassi post-esposizione) prima possibile, idealmente entro poche ore e non oltre 72 ore: «prima è, meglio è»."],["U = U","Undetectable = Untransmittable: con carica virale non rilevabile stabile l'HIV non si trasmette sessualmente."]],
"c-difficile":[["Acqua e sapone, cloro","Le spore resistono all'alcol: lavaggio delle mani con acqua e sapone e pulizia ambientale con prodotti a base di cloro. «Spore? Sapone e cloro»."]],
"meningite":[["Segni di Kernig e Brudzinski","Kernig: dolore estendendo il ginocchio con anca flessa. Brudzinski: flettendo il collo si flettono le ginocchia. Petecchie che non scompaiono alla pressione = meningococco, urgenza."]],
"scabbia":[["Tutti insieme","Si trattano contemporaneamente il paziente e i contatti stretti; lenzuola e indumenti lavati a 60 °C o chiusi in sacchetto per alcuni giorni."]],
/* ---------- ONCOLOGIA ---------- */
"chemioterapia":[["Nadir 7-14","I globuli bianchi raggiungono il punto più basso circa 7-14 giorni dopo il ciclo: è la finestra della neutropenia febbrile."],["Stravaso: ferma, aspira, avvisa","Interrompi l'infusione, aspira il possibile dall'ago, non lavare la linea, avvisa, applica il protocollo specifico (caldo o freddo a seconda del farmaco)."]],
"mucosite":[["Igiene orale delicata","Spazzolino morbido, sciacqui frequenti con soluzioni semplici (fisiologica o bicarbonato), niente collutori alcolici: «morbido, frequente, senza alcol»."]],
"dolore":[["Scala OMS a tre gradini","Lieve: non oppioidi; moderato: oppioidi deboli (± non oppioidi); forte: oppioidi forti. Con gli adiuvanti a ogni gradino. Somministrazione «a orario, per bocca, a gradini, per la persona»."],["NRS","0 nessun dolore, 10 il peggiore immaginabile: 1-3 lieve, 4-6 moderato, 7-10 forte."]],
"cure-palliative":[["L. 38/2010: il dolore come un parametro vitale","Come la febbre (38 °C) si misura e si scrive, così la L. 38/2010 chiede di rilevare il dolore e riportarlo in cartella; garantisce l'accesso a cure palliative e terapia del dolore."]],
"lutto":[["Kübler-Ross: NRPDA","Negazione, Rabbia, Patteggiamento, Depressione, Accettazione. Frase: «Nessuno Resta Per Dimenticare Amore». Non sono tappe obbligate né in ordine fisso."]],
/* ---------- MATERNO-INFANTILE ---------- */
"gravidanza":[["Regola di Naegele","Data presunta del parto = primo giorno dell'ultima mestruazione + 7 giorni − 3 mesi + 1 anno."],["GTPAL","Gravidanze, Termine, Pretermine, Aborti, Living (figli viventi): la formula ostetrica."]],
"preeclampsia":[["140/90 dopo la 20ª settimana + proteinuria o danno d'organo","«Venti settimane, 140 su 90». Segni gravi: cefalea, disturbi visivi, dolore epigastrico. Magnesio solfato: controlla riflessi, respiro e diuresi; antidoto calcio gluconato."]],
"parto":[["Le 3 P del travaglio","Passaggio (bacino), Passeggero (feto), Potenze (contrazioni); più la Psiche della donna."]],
"neonato":[["APGAR","Aspetto (colore), Polso, Grimace (riflessi), Attività (tono), Respiro: 0-2 ciascuno, a 1 e 5 minuti; 7-10 normale."],["Vitamina K e profilassi","Alla nascita: vitamina K (prevenzione della malattia emorragica) e profilassi oculare secondo protocollo."]],
"allattamento":[["Attacco corretto: bocca ben aperta, labbro in fuori","Bocca spalancata, labbro inferiore rovesciato, mento contro il seno, più areola visibile sopra che sotto: «ancora la pancia alla mamma, naso al capezzolo»."],["Almeno 6","Almeno 6 pannolini bagnati al giorno dopo i primi giorni = latte sufficiente."]],
"pediatria-parametri":[["Peso dei bambini","Raddoppia a circa 5 mesi, triplica a 1 anno. Stima del peso (1-10 anni): (età + 4) × 2."],["Frequenze più alte, pressioni più basse","Più il bambino è piccolo, più FC e FR sono alte e la PA bassa. Bradicardia nel lattante = segno grave (spesso da ipossia)."]],
"pediatria-farmaci":[["Sempre in mg/kg","Le dosi pediatriche si calcolano sul peso: «peso, dose, doppio controllo». Usare siringhe dosatrici per uso orale, mai i cucchiai da cucina."]],
/* ---------- PSICHIATRIA ---------- */
"psicofarmaci":[["Litio: acqua e sale","«Il litio ama l'acqua e il sale»: disidratazione, diuretici, FANS e dieta povera di sale ne aumentano i livelli."],["Sindrome serotoninergica vs neurolettica maligna","Serotoninergica: veloce (ore), agitazione, clono, diarrea. Maligna da neurolettici: lenta (giorni), rigidità «a tubo di piombo», febbre alta, CK alta."],["Clozapina: sangue","«Clozapina = conta del sangue»: emocromo regolare per il rischio di agranulocitosi."]],
"astinenza-alcol":[["Tempi: 6-12, 48, 72","Tremori dopo 6-24 ore, convulsioni entro 48 ore, delirium tremens tra 48 e 96 ore. Tiamina prima del glucosio (encefalopatia di Wernicke: confusione, atassia, oftalmoplegia)."]],
"disturbi-alimentari":[["SCOFF","Sick (vomito autoindotto), Control (perdita di controllo), One stone (calo di oltre 6 kg in 3 mesi), Fat (si sente grasso), Food (il cibo domina la vita): 2 risposte positive = sospetto."]],
"salute-mentale-relazione":[["Rischio suicidario: chiedere non induce","Chiedere direttamente dell'idea di suicidio non aumenta il rischio e aiuta a valutarlo."]],
/* ---------- RIABILITAZIONE E GERIATRIA ---------- */
"scale-autonomia":[["ADL e IADL","ADL (Katz) = cose di base (lavarsi, vestirsi, toilette, spostarsi, continenza, alimentarsi: «LaVa-To-S-Co-Al»); IADL (Lawton) = cose strumentali (telefono, spesa, cucina, casa, bucato, trasporti, farmaci, soldi)."],["Barthel","Da 0 a 100: più è alto, più la persona è autonoma."]],
"demenza":[["Le 4 A","Amnesia, Afasia, Aprassia, Agnosia: i disturbi cognitivi tipici."]],
"delirium":[["Acuto e fluttuante","Il delirium inizia in fretta (ore-giorni) e varia nella giornata; la demenza è lenta e stabile. Strumento rapido: 4AT."],["Cause: «PINCH ME»","Pain, INfection, Constipation, Hydration, Medication, Environment: dolore, infezioni, stipsi, idratazione, farmaci, ambiente."]],
"fragilita":[["Le 5 I della geriatria","Immobilità, Instabilità (cadute), Incontinenza, Intellettuale (deterioramento e delirium), Iatrogenesi."]],
"incontinenza":[["Tipi: da sforzo, da urgenza, da rigurgito, funzionale","Sforzo = tosse o starnuto; urgenza = «non faccio in tempo»; rigurgito = vescica troppo piena che gocciola; funzionale = non riesce ad arrivare al bagno."]],
"lesione-midollare":[["Disreflessia autonomica","Lesioni sopra T6: ipertensione improvvisa, bradicardia, cefalea, sudorazione sopra la lesione. Siedi la persona e cerca lo stimolo (vescica piena, catetere piegato, feci): «siediti e svuota»."]],
/* ---------- NUTRIZIONE ---------- */
"nutrizione-basi":[["IMC","Peso in kg diviso altezza in metri al quadrato: < 18,5 sottopeso, 18,5-24,9 normopeso, 25-29,9 sovrappeso, ≥ 30 obesità."],["MUST","Malnutrition Universal Screening Tool: IMC, calo di peso non voluto, malattia acuta con digiuno: tre domande per lo screening."]],
"nutrizione-enterale":[["Testa su di 30-45°","Durante la nutrizione e per almeno 30-60 minuti dopo: «la testa alta, la sonda sicura». Lavaggio della sonda con acqua prima e dopo i farmaci e ogni 4 ore."]],
"nutrizione-parenterale":[["Via dedicata","Linea dedicata, nessun farmaco aggiunto, cambio del set ogni 24 ore per le miscele con lipidi, controllo della glicemia."]],
"sindrome-rialimentazione":[["Start low, go slow","Si inizia piano con le calorie, tiamina prima, fosforo, potassio e magnesio ogni giorno: «parti piano, vai piano»."]],
/* ---------- DIAGNOSTICA ---------- */
"esami-laboratorio":[["Ordine delle provette","Emocolture → citrato (azzurro, coagulazione) → siero (rosso o giallo) → eparina (verde) → EDTA (viola, emocromo) → fluoruro (grigio, glicemia). Frase: «Emo Ci Sorride, Ecco Elegante Felicità» (Emocolture, Citrato, Siero, Eparina, EDTA, Fluoruro)."]],
"esame-obiettivo":[["IPPA, nell'addome IAPP","Ispezione, Palpazione, Percussione, Auscultazione; nell'addome si ausculta prima di palpare per non alterare la peristalsi."]],
"occhio":[["Pupille: PERRLA","Pupille Eguali, Rotonde, Reagenti alla Luce e all'Accomodazione."]],
/* ---------- LAVORO ---------- */
"ml-figure":[["DL, RSPP, MC, RLS","Datore di Lavoro (responsabile), RSPP (organizza la prevenzione), Medico Competente (sorveglianza sanitaria), RLS (rappresenta i lavoratori): «chi decide, chi organizza, chi visita, chi rappresenta»."]],
"ml-dvr":[["Il DVR non si delega","La valutazione dei rischi e la nomina dell'RSPP sono gli obblighi che il datore di lavoro non può delegare (art. 17 D.Lgs. 81/2008)."]],
"ml-infortuni":[["Prognosi > 3 giorni = denuncia","Infortunio con prognosi oltre 3 giorni: denuncia all'INAIL entro 2 giorni dal certificato. Da 1 a 3 giorni: comunicazione statistica. «Tre giorni, due giorni»."]],
"ml-mmc":[["NIOSH e schiena dritta","Ginocchia piegate, schiena dritta, carico vicino al corpo, niente torsioni. Per i pazienti: usare gli ausili (sollevatori, teli ad alto scorrimento)."]],
"ml-fisici":[["Rumore: 80-85-87","80 dB(A) azione inferiore (DPI a disposizione), 85 azione superiore (DPI obbligatori), 87 valore limite."],["Radiazioni: tempo, distanza, schermatura","Ridurre il tempo, aumentare la distanza, usare le schermature (camice piombato, collare tiroideo)."]],
"ml-vdt":[["20 ore e pause","Videoterminalista = almeno 20 ore settimanali; pausa di 15 minuti ogni 2 ore. Regola 20-20-20: ogni 20 minuti guarda a 20 piedi (6 metri) per 20 secondi."]],
"ml-dpi":[["Tre categorie","I = rischi lievi; II = rischi intermedi; III = rischi gravi o mortali (es. FFP2/FFP3, protezione da agenti biologici): «la terza è la più seria e richiede addestramento»."]],
"ml-emergenze":[["RACE e PASS","Incendio: Rescue (salva chi è in pericolo), Alarm (dai l'allarme), Contain (chiudi le porte), Extinguish/Evacuate. Estintore: Pull (togli la spina), Aim (punta alla base della fiamma), Squeeze (premi), Sweep (muovi a ventaglio)."]],
"ml-stress":[["Valutare anche lo stress","Lo stress lavoro-correlato fa parte della valutazione dei rischi (art. 28 D.Lgs. 81/2008): indicatori oggettivi, poi percezione dei lavoratori."]],
/* ---------- DIRITTO ---------- */
"dir-fonti":[["La piramide","Costituzione e leggi costituzionali → leggi ordinarie e atti con forza di legge (decreti-legge, decreti legislativi) → regolamenti → consuetudini. Decreto-legge: «60 giorni per diventare legge»."]],
"dir-costituzione":[["Art. 32","«32 = salute»: la Repubblica tutela la salute come diritto fondamentale e interesse della collettività; nessuno può essere obbligato a un trattamento sanitario se non per legge."]],
"dir-cp-generale":[["Dolo, colpa, preterintenzione","Dolo = volevi l'evento; colpa = non lo volevi ma hai sbagliato (negligenza, imprudenza, imperizia); preterintenzione = volevi un evento minore ed è successo di più."]],
"dir-professione":[["Le tre leggi della professione","42/1999 (fine del mansionario, «professione sanitaria»), 251/2000 (autonomia e dirigenza), 43/2006 (iscrizione obbligatoria all'albo, coordinatori e specialisti): «42-251-43». La 3/2018 trasforma i collegi in ordini (OPI)."]],
"dir-l194":[["90 giorni","Interruzione volontaria di gravidanza entro i primi 90 giorni; dopo, solo per gravi motivi di salute della donna."]],
"dir-l104":[["3 giorni al mese","Permessi per assistere un familiare con disabilità grave: 3 giorni al mese (art. 33): «104 = 3 giorni»."]],
"dir-raccomandazioni":[["Le più chieste","1 = potassio concentrato; 2 = garze e strumenti dimenticati nel campo operatorio; 3 = paziente, procedura e lato sbagliati; 7 = errori di terapia; 13 = cadute; 17 = riconciliazione; 19 = forme farmaceutiche orali solide. «1 K, 2 garze, 3 lato, 7 terapia, 13 cadute»."]],
"dir-codice-rosso":[["Tre giorni","Il pubblico ministero sente la vittima di violenza domestica o di genere entro 3 giorni dall'iscrizione della notizia di reato (L. 69/2019)."]],
"dir-tu-stup":[["DPR 309/1990: tabelle, registro, armadio","Tre parole per il Testo unico sugli stupefacenti: tabelle (classificano le sostanze), registro di carico e scarico, armadio chiuso a chiave."]],
/* ---------- CODICE DEONTOLOGICO ---------- */
"codice-deontologico":[["2025: 8 capi e 54 articoli","Codice FNOPI approvato nel 2025 e in vigore dal 22 marzo 2025: «8 capi, 54 articoli»."]],
/* ---------- ESAMI ---------- */
"es-lettura":[["Cinque domande al referto","Di chi è? Che cosa è alterato? Com'era prima? Che cosa c'entra con la clinica? Chi devo avvisare?"]],
"es-emocromo":[["Ht ≈ 3 × Hb","Regola del tre: l'ematocrito è circa il triplo dell'emoglobina (Hb 13 ≈ Ht 39%)."]],
"es-indici":[["MCV: piccolo = ferro, grande = B12","«Pochi e piccoli: manca il ferro; pochi e grandi: manca la B12 o i folati»."]],
"es-leucociti":[["Ordine della formula","Neutrofili, Linfociti, Monociti, Eosinofili, Basofili: «Non Lasciare Mai Esami Banali» (dal più al meno numeroso)."]],
"es-piastrine":[["4 T per la HIT","Thrombocytopenia (calo), Timing (5-10 giorni), Thrombosis (trombosi), oTher causes (nessun'altra causa): lo score delle 4 T."]],
"es-coagulazione":[["WEPT e HINT","Warfarin → Estrinseca → PT (INR). Heparin → INTrinseca → PTT (aPTT)."]],
"es-fibrinogeno-ddimero":[["D-dimero: Dice No","Un D-dimero normale «dice no» alla trombosi (se la probabilità è bassa); se è alto non dice sì."]],
"es-creatinina":[["Muscolo grande, creatinina alta","La creatinina dipende dai muscoli: in un anziano magro un valore «normale» può nascondere un rene che filtra poco. Guarda l'eGFR."]],
"es-colestasi":[["Feci chiare, urine scure","Colestasi: la bilirubina non arriva all'intestino (feci color argilla) e passa nelle urine (color marsala)."]],
"es-transaminasi":[["ALT = Liver","ALT è più specifica per il fegato (L come Liver); AST si trova anche in muscolo e cuore. AST/ALT > 2: pensare all'alcol."]],
"es-ck":[["Urine color tè = muscolo rotto","CK altissima e urine scure dopo una lunga permanenza a terra = rabdomiolisi: «acqua, acqua, acqua» e controllo del potassio."]],
"es-bnp":[["BNP basso esclude","«BNP basso, cuore a posto (probabilmente)»: serve soprattutto a escludere lo scompenso."]],
"es-glicemia":[["70-100-126-200","Ipoglicemia < 70; normale a digiuno < 100; alterata 100-125; diabete ≥ 126 a digiuno (confermata) o ≥ 200 casuale con sintomi."]],
"es-sodio-potassio":[["Prima di trattare un K alto: emolisi?","«K alto senza ECG? Rifai il prelievo». Laccio corto, niente pugno, analisi rapida."]],
"es-calcio":[["Ossa, calcoli, lamenti e confusione","Ipercalcemia: dolori ossei, calcoli renali, dolori addominali (stipsi) e disturbi psichici (confusione)."],["Calcio corretto","Calcio + 0,8 × (4 − albumina): «ottanta centesimi per ogni grammo che manca»."]],
"es-acido-base":[["Gap anionico: «Na meno il resto»","Na − (Cl + HCO3): normale circa 10 (8-12). Le cause di gap alto sono quelle di MUDPILES."]],
"es-ferro":[["Ferritina bassa = certo; alta = forse","La ferritina bassa dà la carenza per certa; quella alta può essere solo infiammazione."]],
"es-tdm":[["Valle = prima, picco = dopo","«In valle si scende prima della dose»: il prelievo di valle si fa subito prima della somministrazione."]],
"es-sierologia":[["Epatite B: S = Sì infezione, anti-S = Sicuro","HBsAg positivo = c'è il virus; anti-HBs positivo = protetto (vaccino o guarigione); anti-HBc = ha incontrato il virus (il vaccino non lo fa comparire)."]],
"es-coombs":[["Diretto sulle cellule, indiretto nel siero","Coombs Diretto = anticorpi già attaccati ai globuli rossi (Dentro); Indiretto = anticorpi liberi nel siero (In giro)."]]
};
/* Enciclopedia — parte 14: ecografia ed eco-Doppler per l'infermiere (contenuti rielaborati; fonti: raccomandazioni internazionali sull'ecografia polmonare 2012, linee guida ecocardiografiche sulla vena cava, revisioni sistematiche sugli accessi venosi ecoguidati eseguiti da infermieri) */
ENC_AREE.eco={n:"Ecografia ed eco-Doppler",c:"var(--tr)"};
ENC.push(
{id:"eco-principi",a:"eco",s:"Basi fisiche",t:"Ecografia: come si forma l'immagine",
 d:"L'ecografia usa ultrasuoni (frequenze oltre 20.000 Hz, in clinica di solito tra 2 e 15 MHz) prodotti da cristalli piezoelettrici nella sonda: gli echi riflessi dai tessuti diventano punti più o meno luminosi sullo schermo (B-mode, «brightness mode»).",
 v:[["Anecogeno (nero)","liquidi: sangue nei vasi, urina, bile, versamenti, cisti"],["Ipoecogeno (grigio scuro)","tessuti con pochi echi: muscolo, linfonodi, trombo recente"],["Isoecogeno","stessa luminosità del tessuto vicino"],["Iperecogeno (bianco)","interfacce forti: osso, calcoli, aria, pleura, fasce, aghi"],["Frequenza alta (lineare 7-15 MHz)","immagine più definita ma poco profonda: vasi superficiali, pleura"],["Frequenza bassa (convex 2-6 MHz)","immagine meno definita ma profonda: addome, vescica"]],
 p:["Gli ultrasuoni si riflettono dove cambia l'impedenza acustica dei tessuti (interfacce): più grande la differenza, più forte l'eco","L'aria riflette quasi tutto il fascio: per questo si usa il gel, che elimina l'aria tra sonda e pelle","Le ossa e i calcoli riflettono molto e lasciano dietro di sé un cono d'ombra","L'ecografia non usa radiazioni ionizzanti; si applica comunque il principio di usare l'energia più bassa per il tempo più breve necessario: sullo schermo sono indicati l'indice meccanico (MI) e l'indice termico (TI)","Orientamento: il marcatore della sonda corrisponde al simbolo sullo schermo; in scansione trasversale il lato destro del paziente compare di solito a sinistra dello schermo","Il risultato dipende molto dall'operatore: servono formazione e pratica supervisionata"],
 i:["Spiega l'esame e la preparazione (per l'addome superiore: digiuno; per la vescica: vescica piena se richiesto)","Pulisce e disinfetta la sonda tra un paziente e l'altro secondo le indicazioni del produttore; per procedure invasive usa copri-sonda e gel sterili"],
 e:["Usare troppo poco gel (immagine nera o con bande scure)","Confondere un'area anecogena con «assenza di tessuto»: spesso è liquido"],
 r:["eco-sonde","eco-artefatti","imaging"]},
{id:"eco-sonde",a:"eco",s:"Sonde e comandi",t:"Sonde, modalità e comandi dell'ecografo",
 d:"La scelta della sonda e la regolazione di profondità, guadagno e fuoco determinano la qualità dell'immagine.",
 v:[["Sonda lineare","immagine rettangolare, alta frequenza: vasi, accessi venosi, pleura, tessuti superficiali, nervi"],["Sonda convex","immagine a ventaglio, bassa frequenza: addome, vescica, eFAST, polmone in profondità"],["Sonda settoriale (phased array)","piccola superficie di appoggio, bassa frequenza: cuore tra le coste"],["B-mode","immagine bidimensionale in scala di grigi"],["Modo M","una sola linea dell'immagine registrata nel tempo: movimenti della pleura, della vena cava, delle valvole"],["Color Doppler","flusso colorato sopra l'immagine: di solito rosso verso la sonda, blu in allontanamento"],["Doppler pulsato (PW)","spettro delle velocità in un punto preciso del vaso (volume campione)"]],
 p:["Profondità: va regolata in modo che la struttura da studiare occupi la parte centrale dello schermo","Guadagno (gain): aumenta o riduce la luminosità di tutta l'immagine; il TGC la regola per fasce di profondità","Troppo guadagno riempie di falsi echi i vasi e le raccolte; troppo poco fa sparire strutture deboli","Il fuoco (indicato da un triangolino sul righello della profondità) va posto all'altezza della struttura da studiare","Freeze blocca l'immagine per osservarla e misurarla; i calibri permettono di misurare distanze, aree e volumi","Per i vasi si usano due assi: asse corto (sonda trasversale, il vaso appare come un cerchio) e asse lungo (sonda parallela al vaso, appare come un tubo)"],
 e:["Usare la sonda lineare per un organo profondo (non si vede nulla oltre pochi centimetri)","Misurare senza congelare l'immagine"],
 r:["eco-principi","eco-doppler"]},
{id:"eco-artefatti",a:"eco",s:"Artefatti utili",t:"Artefatti ecografici: quando un «errore» aiuta la diagnosi",
 d:"Gli artefatti sono immagini che non corrispondono a strutture reali ma sono prodotte dal modo in cui si propagano gli ultrasuoni; molti sono utili per riconoscere liquidi, calcoli e aria.",
 v:[["Cono d'ombra posteriore","banda nera dietro calcoli e ossa, che riflettono quasi tutto il fascio"],["Rinforzo posteriore","zona più luminosa dietro una raccolta liquida (vescica, cisti), che attenua poco il fascio"],["Riverbero (linee A)","linee orizzontali ripetute dietro la pleura o un ago: il fascio rimbalza tra due superfici"],["Linee B (coda di cometa)","linee verticali luminose dalla pleura al fondo dello schermo: setti interstiziali ispessiti o pieni di liquido"],["Immagine a specchio","una struttura appare duplicata dietro una superficie molto riflettente (per esempio il diaframma)"],["Aliasing","nel Doppler, velocità più alte della scala impostata appaiono invertite o a mosaico"]],
 p:["Un'area nera con rinforzo posteriore è quasi sempre liquida; un'immagine bianca con ombra posteriore è un calcolo o un osso","Le linee A sono normali nel polmone aerato; le linee B numerose indicano una sindrome interstiziale","L'ago in asse corto produce un punto luminoso con una piccola coda di riverbero"],
 r:["eco-principi","eco-polmone","eco-doppler"]},
{id:"eco-doppler",a:"eco",s:"Doppler",t:"Eco-Doppler: color, power e Doppler pulsato",
 d:"L'effetto Doppler è la variazione di frequenza dell'eco riflesso da strutture in movimento (i globuli rossi): aumenta se il sangue si avvicina alla sonda, diminuisce se si allontana. L'ecografo lo trasforma in colori, suoni e spettri di velocità.",
 v:[["Color Doppler","direzione e velocità media del flusso in una finestra colorata: rosso verso la sonda, blu in allontanamento (la convenzione si può invertire: guarda la barra dei colori)"],["Power Doppler","mostra la presenza di flusso, anche lento, ma non la direzione"],["Doppler pulsato (PW)","velocità nel tempo in un punto preciso; sopra la linea di base il flusso verso la sonda"],["Doppler continuo (CW)","misura velocità molto alte, ma senza sapere a che profondità"],["Velocità sistolica di picco (PSV)","la più alta del ciclo cardiaco"],["Velocità telediastolica (EDV)","quella alla fine della diastole"],["Indice di resistenza (RI)","(PSV − EDV) ÷ PSV: vicino a 1 nelle arterie ad alta resistenza, più basso in quelle a bassa resistenza"]],
 p:["L'angolo tra fascio e vaso deve essere di 60° o meno per misurare correttamente le velocità; a 90° il Doppler non registra flusso","La scala di velocità (PRF) va adattata: troppo bassa produce aliasing, troppo alta fa sparire i flussi lenti","Lo spettro normale di un'arteria ha una «finestra» scura sotto la curva: il flusso è ordinato (laminare); con la turbolenza la finestra si riempie (allargamento spettrale)","Il color Doppler aiuta a distinguere un vaso da una struttura liquida e un'arteria da una vena prima di una puntura"],
 e:["Concludere che non c'è flusso senza aver controllato angolo, scala e guadagno del colore","Leggere il colore senza guardare la barra dei colori"],
 r:["eco-onde-doppler","eco-sonde","eco-artefatti"]},
{id:"eco-onde-doppler",a:"eco",s:"Forme d'onda",t:"Forme d'onda Doppler di arterie e vene",
 d:"La forma dello spettro Doppler indica la resistenza dei vasi a valle e la presenza di stenosi o ostruzioni; i documenti di consenso delle società di medicina vascolare raccomandano di descriverla in base a direzione, fasicità e resistenza.",
 v:[["Arteria degli arti a riposo","alta resistenza: picco sistolico rapido, breve flusso invertito, poco o nessun flusso in diastole (trifasica o multifasica)"],["Arterie di cervello, reni e fegato","bassa resistenza: flusso continuo anche in diastole"],["A valle di una stenosi o occlusione","monofasica smorzata: salita lenta, picco basso e arrotondato («tardus parvus»)"],["Nel punto di stenosi","velocità molto alte, allargamento spettrale, aliasing al color; a valle turbolenza"],["Vena normale degli arti inferiori","flusso fasico con il respiro, che aumenta comprimendo i muscoli a valle (augmentation)"],["Vena con flusso continuo e piatto","perdita della fasicità: ostruzione più a monte (vene iliache, cava)"],["Assenza di flusso","occlusione arteriosa o trombosi venosa (da confermare con la compressione)"],["Flusso venoso molto pulsatile","sovraccarico di liquidi, insufficienza della tricuspide o del ventricolo destro"]],
 p:["Dopo l'esercizio o in caso di infezione e calore la resistenza si abbassa e anche un'arteria periferica normale mostra flusso diastolico","Un'onda monofasica in un piede freddo e dolente fa pensare a ischemia: va segnalata subito","Nelle vene degli arti inferiori il flusso si riduce in inspirazione (aumenta la pressione addominale) e riprende in espirazione"],
 r:["eco-doppler","eco-tvp","ipertensione"]},
{id:"eco-accessi",a:"eco",s:"Accessi ecoguidati",t:"Accessi venosi periferici con guida ecografica",
 d:"Nelle persone con vene difficili (non visibili né palpabili, precedenti fallimenti, obesità, edema, uso di sostanze, molte terapie endovena) la guida ecografica aumenta il successo al primo tentativo. Revisioni sistematiche recenti su procedure eseguite da infermieri mostrano più successi al primo tentativo e meno punture.",
 v:[["Vena: aspetto","ovale, parete sottile, si schiaccia con una lieve pressione della sonda, nessun flusso pulsatile"],["Arteria: aspetto","rotonda, parete spessa, pulsante, non si schiaccia; al color flusso che cambia a ogni battito"],["Asse corto (out-of-plane)","vaso come un cerchio, si vede solo una sezione dell'ago: va seguita la punta a piccoli passi"],["Asse lungo (in-plane)","si vede tutto l'ago, ma è più difficile mantenere il vaso nel fascio"]],
 p:["Prima di pungere si valutano profondità, calibro, decorso e comprimibilità della vena e la distanza da arterie e nervi","Si preferiscono vene non troppo profonde, rettilinee e di calibro adeguato al catetere: più è profonda la vena, più lungo deve essere il catetere perché una buona parte resti nel vaso","Tecnica di posizionamento dinamico della punta: si sposta la sonda in avanti finché la punta scompare, poi si avanza l'ago finché ricompare, e così via","Per gli accessi si usano copri-sonda sterile e gel sterile monodose, con la stessa antisepsi cutanea della tecnica tradizionale","La punta che compare sotto la vena indica il passaggio della parete posteriore: si ritira lentamente finché torna nel lume"],
 i:["Valuta il rischio di accesso difficile già all'ingresso e chiede la guida ecografica prima di molti tentativi alla cieca","Documenta vena, profondità, calibro del catetere, numero di tentativi e complicanze","Controlla il sito come per ogni accesso periferico (infiltrazione, flebite)"],
 e:["Seguire il corpo dell'ago credendo che sia la punta","Pungere un vaso senza aver verificato che si schiacci (rischio di puntura arteriosa)","Usare cateteri corti in vene profonde (rischio di fuoriuscita)"],
 r:["cvc","eco-sonde","eco-doppler"]},
{id:"eco-vescica",a:"eco",s:"Vescica",t:"Ecografia vescicale e bladder scanner",
 d:"La vescica piena è anecogena con rinforzo posteriore. Il volume si stima con l'ecografia o con il bladder scanner, uno strumento portatile che calcola il volume in automatico.",
 v:[["Formula dell'ellissoide","larghezza × profondità × lunghezza (cm) × 0,52 = volume in ml"],["Residuo post-minzionale","urina che resta dopo la minzione: le soglie di intervento dipendono dal protocollo e dalla persona"],["Palloncino del catetere","piccolo cerchio anecogeno con parete luminosa dentro la vescica"]],
 p:["Misurare il volume prima di posizionare un catetere riduce i cateterismi inutili e quindi le infezioni urinarie associate","Dopo un intervento, con anestesia spinale o in chi assume oppioidi o anticolinergici la ritenzione è frequente e spesso non dolorosa nell'anziano","Il bladder scanner può sbagliare in caso di ascite, cisti pelviche, utero gravido, obesità o cicatrici: se il valore non torna con la clinica si verifica","Con il catetere in sede, una vescica piena intorno al palloncino indica che il drenaggio è ostruito (pieghe del tubo, coaguli, incrostazioni)"],
 i:["Posiziona la persona supina, mette il gel sopra il pube e orienta la sonda come indicato dallo strumento","Registra volume, ora e ultima minzione; segnala i valori oltre la soglia del protocollo"],
 e:["Eseguire il cateterismo senza aver misurato il volume quando lo strumento è disponibile","Fidarsi di una sola misura in presenza di ascite"],
 r:["cateterismo","incontinenza","eco-principi"]},
{id:"eco-polmone",a:"eco",s:"Polmone",t:"Ecografia polmonare",
 d:"Il polmone normale è pieno d'aria e mostra soprattutto artefatti: la linea pleurica che scivola con il respiro e le linee A. Le raccomandazioni internazionali di consenso (2012) descrivono i segni principali di sindrome interstiziale, pneumotorace, consolidamento e versamento.",
 v:[["Scivolamento pleurico (sliding)","movimento della linea pleurica con il respiro: esclude il pneumotorace in quel punto"],["Linee A","linee orizzontali ripetute: polmone aerato (normale, ma presenti anche nel pneumotorace)"],["Linee B","linee verticali luminose dalla pleura al fondo; 3 o più per campo indicano sindrome interstiziale (edema, polmonite, ARDS)"],["Pneumotorace","assenza di scivolamento e di linee B; il «punto polmone» lo conferma; in modo M «codice a barre»"],["Modo M normale","«riva del mare»: righe orizzontali sopra la pleura, aspetto granulare sotto"],["Consolidamento","polmone che assomiglia al fegato (epatizzazione), a volte con broncogramma aereo"],["Versamento","raccolta anecogena sopra il diaframma, con colonna visibile sopra il diaframma"]],
 p:["Nell'edema polmonare cardiogeno le linee B sono diffuse e bilaterali e si riducono con la terapia decongestionante","Le linee B localizzate, con consolidamento, orientano verso una polmonite","L'ecografia è più sensibile della radiografia a letto per pneumotorace e versamento"],
 i:["Durante la toracentesi ecoguidata prepara la persona seduta, il materiale sterile e il monitoraggio, sorveglia dolore, tosse e dispnea"],
 e:["Considerare le linee A un segno di polmone sicuramente sano: senza scivolamento possono indicare pneumotorace"],
 r:["eco-artefatti","scompenso","pneumotorace"]},
{id:"eco-fast",a:"eco",s:"eFAST",t:"eFAST nel trauma",
 d:"Ecografia rapida al letto del traumatizzato per cercare liquido libero (sangue) nell'addome e nel pericardio e, nella versione estesa, pneumotorace ed emotorace.",
 v:[["Spazio di Morison (epato-renale)","tra fegato e rene destro: il punto da guardare per primo"],["Finestra spleno-renale","tra milza e rene sinistro"],["Finestra pelvica","dietro la vescica (cavo del Douglas nella donna)"],["Finestra sottoxifoidea","versamento pericardico"],["Torace anteriore","scivolamento pleurico: pneumotorace"]],
 p:["Il liquido libero appare come una striscia anecogena nelle zone più declivi","Una eFAST positiva in un paziente instabile orienta di solito verso la sala operatoria; una eFAST negativa non esclude lesioni (si ripete e si completa con la TC se il paziente è stabile)","Si esegue durante la valutazione primaria senza ritardare la rianimazione"],
 i:["Prepara due accessi venosi di grosso calibro, prelievi per gruppo e prove crociate, riscaldamento dei liquidi e preparazione alla trasfusione"],
 r:["trauma","shock","eco-polmone"]},
{id:"eco-vci",a:"eco",s:"Vena cava",t:"Vena cava inferiore: diametro e collassabilità",
 d:"Nel respiro spontaneo la vena cava inferiore si riduce in inspirazione. Diametro e variazione respiratoria aiutano a stimare la pressione dell'atrio destro (raccomandazioni ecocardiografiche).",
 v:[["≤ 2,1 cm e collasso > 50%","pressione atrio destro bassa, circa 3 mmHg (0-5)"],["> 2,1 cm e collasso < 50%","pressione atrio destro alta, circa 15 mmHg (10-20)"],["Situazioni intermedie","circa 8 mmHg (5-10)"]],
 p:["Si misura in sottocostale, in asse lungo, a 1-2 cm dallo sbocco nell'atrio destro, anche con il modo M","Non vale nel paziente in ventilazione a pressione positiva e va interpretata con cautela con pressione addominale alta","Una cava piccola e molto collassabile, con ipotensione, orienta verso l'ipovolemia; una cava dilatata e fissa verso sovraccarico o scompenso destro","La risposta ai liquidi si verifica comunque sul paziente: pressione, frequenza, diuresi, segni di sovraccarico"],
 r:["shock","scompenso","eco-sonde"]},
{id:"eco-tvp",a:"eco",s:"Trombosi venosa",t:"Ecografia con compressione nella trombosi venosa profonda",
 d:"Una vena normale si chiude completamente sotto una lieve pressione della sonda; una vena che non si comprime contiene un trombo. La compressione su due punti (inguine e cavo popliteo) è un esame rapido di primo livello.",
 p:["Il trombo recente può essere quasi anecogeno: per questo si usa la compressione e non solo l'aspetto","Al Doppler la vena trombizzata non ha flusso e non aumenta comprimendo il polpaccio","Un esame negativo con alto sospetto clinico va ripetuto o completato secondo il percorso diagnostico"],
 i:["Non massaggia l'arto, somministra l'anticoagulante prescritto, sorveglia segni di embolia polmonare (dispnea improvvisa, dolore toracico, tachicardia, desaturazione)","Educa la persona alla terapia anticoagulante e ai segni di sanguinamento"],
 r:["tev","eco-onde-doppler"]},
{id:"eco-infermiere",a:"eco",s:"Ruolo infermieristico",t:"Ecografia al letto del paziente: ambiti dell'infermiere",
 d:"L'ecografia al letto del paziente (POCUS) è usata sempre più spesso dagli infermieri per procedure e controlli mirati, all'interno delle proprie competenze, con formazione certificata e protocolli aziendali. La diagnosi ecografica resta medica.",
 p:["Ambiti più diffusi: accessi venosi periferici ecoguidati, scelta della vena e posizionamento di midline e PICC, misura del volume vescicale, verifica del palloncino del catetere","In area critica: supporto al monitoraggio (per esempio linee B nello scompenso) secondo protocolli condivisi","La competenza si acquisisce con formazione teorica, pratica supervisionata e numero minimo di procedure documentate","L'infermiere documenta ciò che ha visto e fatto e segnala al medico i reperti anomali o dubbi"],
 i:["Mantiene la sonda pulita e integra e verifica la disinfezione dopo ogni uso","Rispetta la riservatezza delle immagini salvate (dati sanitari)"],
 r:["eco-accessi","eco-vescica","responsabilita-professionale"]}
);
