 "eco-principi":[["«Liquido = nero, osso e calcoli = bianco»","Anecogeno ciò che non riflette (liquidi), iperecogeno ciò che riflette molto (osso, calcoli, aria)."],["«Alta frequenza, alta definizione, poca profondità»","Sonda lineare per ciò che è superficiale, convex per ciò che è profondo."]],
 "eco-doppler":[["BART: Blu Allontanamento, Rosso verso (Toward)","Nella convenzione più usata il rosso indica flusso verso la sonda e il blu in allontanamento: controlla sempre la barra dei colori."],["«Sessanta o meno»","Angolo Doppler ≤ 60° per misure di velocità affidabili."]],
 "eco-polmone":[["«A = Aria, B = Bagnato»","Linee A: polmone aerato. Linee B: polmone con più liquido nell'interstizio."],["«Mare o codice a barre»","Modo M: riva del mare se la pleura scivola, codice a barre se non scivola (pneumotorace)."]],
 "eco-tvp":[["«Se non si schiaccia, c'è un trombo»","La vena normale si chiude sotto la sonda; quella trombizzata resta aperta."]],
 "eco-vci":[["«2,1 e 50»","Cava ≤ 2,1 cm che collassa più del 50%: pressione atriale destra bassa; sopra 2,1 cm e meno del 50%: alta."]],
