/* Enciclopedia — parte 15: ecografia, approfondimenti (semeiotica B-mode, regolazioni, rene, aorta, protocolli al letto, procedure ecoguidate). Contenuti rielaborati e verificati su linee guida e manuali di ecografia; nessun testo riprodotto. */
ENC.push(
{id:"eco-semeiotica",a:"eco",s:"Leggere l'immagine",t:"Semeiotica di base: descrivere ciò che si vede in B-mode",
 d:"Prima di interpretare si descrive: ecogenicità (quanto è chiara una struttura rispetto ai tessuti vicini), omogeneità, margini, forma, dimensioni e artefatti che la accompagnano. Le stesse parole servono per il referto e per comunicare con il medico.",
 v:[["Ecostruttura omogenea","echi distribuiti in modo regolare, come in un fegato o una tiroide normali"],["Ecostruttura disomogenea","zone più chiare e più scure mescolate: tessuto alterato, raccolta organizzata, trombo vecchio"],["Formazione cistica semplice","nera, a pareti sottili e regolari, con rinforzo posteriore e piccole ombre ai lati: è liquida e quasi sempre benigna"],["Formazione cistica complessa","setti spessi, echi interni, parti solide o pareti irregolari: va approfondita"],["Formazione solida","produce echi al suo interno e non ha rinforzo posteriore netto; il color Doppler può mostrare vasi"],["Calcolo o calcificazione","bianco con ombra posteriore netta e «pulita»"],["Gas","bianco con ombra «sporca», piena di riverberi"]],
 p:["Si confronta sempre l'ecogenicità con un riferimento vicino (per esempio il rene con il fegato) e non con un valore assoluto, perché dipende dalle regolazioni","Una struttura va vista in due piani perpendicolari prima di descriverla: un vaso tagliato di traverso può sembrare una cisti","Le pareti di una struttura curva colpite di striscio producono piccole ombre laterali (artefatto da bordo)","Anche alcune lesioni solide molto omogenee possono mostrare un lieve rinforzo posteriore: il rinforzo è tipico ma non esclusivo del liquido","Nelle parti più profonde il fascio arriva attenuato: un tessuto normale può sembrare più scuro se il TGC non è regolato"],
 i:["Usa termini descrittivi (anecogeno, ipoecogeno, ombra, rinforzo) e non diagnosi, quando riferisce un'immagine osservata al letto","Conosce il proprio campo di competenza: l'ecografia infermieristica risponde a domande semplici e mirate (vescica piena o vuota, vena idonea, palloncino in sede)"],
 e:["Descrivere un'immagine vista in un solo piano","Chiamare «cisti» un'area scura senza aver verificato rinforzo posteriore e assenza di flusso"],
 r:["eco-principi","eco-artefatti","eco-regolazioni"]},
{id:"eco-regolazioni",a:"eco",s:"Ottimizzare l'immagine",t:"Regolare l'ecografo: guadagno, TGC, profondità, fuoco e frequenza",
 d:"Una buona immagine si ottiene in pochi passaggi sempre uguali: scegliere sonda e preset, impostare la profondità, regolare il guadagno e il TGC, posizionare il fuoco e, se serve, attivare funzioni come l'armonica tissutale o il compound.",
 v:[["Preset","pacchetto di regolazioni pensato per un distretto (vasi, addome, vescica, polmone): è il punto di partenza"],["Profondità","la struttura di interesse deve stare nella metà centrale dello schermo"],["Guadagno (gain)","amplifica tutti gli echi di ritorno: il sangue e l'urina devono restare neri"],["TGC","cursori che regolano il guadagno per fasce di profondità e compensano l'attenuazione"],["Fuoco","zona in cui il fascio è più stretto e l'immagine più nitida: va portato all'altezza del bersaglio"],["Imaging armonico","usa gli echi a frequenza doppia generati nei tessuti: immagine più pulita e meno artefatti nelle strutture liquide"],["Compound spaziale","combina scansioni con angoli diversi: bordi più netti e meno rumore, ma può attenuare ombre e rinforzi utili"]],
 p:["Ordine pratico: sonda, preset, profondità, guadagno e TGC, fuoco, poi zoom e misure","Troppo guadagno può far sembrare piena di echi una vena normale e simulare un trombo; prima di concludere si ricontrollano le regolazioni e si prova a comprimere","Per strutture profonde si sceglie una frequenza più bassa (più penetrazione), per quelle superficiali una più alta (più dettaglio)","Il gas intestinale si sposta spesso con una pressione dolce e progressiva della sonda o cambiando la posizione della persona","Ogni ecografo mostra sullo schermo gli indici meccanico (MI) e termico (TI): si mantengono i più bassi possibili, soprattutto in gravidanza e sugli occhi"],
 e:["Aumentare il guadagno per «vedere meglio» una zona profonda invece di abbassare la frequenza o regolare il TGC","Lasciare il fuoco in superficie mentre si studia un organo profondo"],
 r:["eco-sonde","eco-semeiotica","eco-accessi"]},
{id:"eco-rene",a:"eco",s:"Rene e vie urinarie",t:"Ecografia del rene: idronefrosi e calcoli",
 d:"Il rene si studia con la sonda convex dal fianco, in asse lungo e corto. È ovale, con la corticale grigia all'esterno e il seno renale chiaro al centro (per il grasso). Quando l'urina non defluisce, bacinetto e calici si dilatano e appaiono come spazi neri ramificati e comunicanti: idronefrosi.",
 v:[["Rene adulto normale","lunghezza di circa 10-12 cm, contorno regolare, corticale di spessore uniforme"],["Idronefrosi lieve","solo il bacinetto è dilatato"],["Idronefrosi moderata","bacinetto e calici dilatati, corticale ancora conservata"],["Idronefrosi grave","cavità molto dilatate e corticale assottigliata"],["Calcolo","immagine bianca con cono d'ombra; al color Doppler può comparire un «luccichio» colorato dietro il calcolo (twinkling)"],["Jet ureterale","con il color Doppler si vede lo spruzzo di urina che entra in vescica: se manca da un lato, quel lato può essere ostruito"]],
 p:["Cause ostruttive: calcoli, ostacoli prostatici, tumori, compressioni esterne, coaguli","Cause di dilatazione senza ostruzione: vescica molto piena, gravidanza, reflusso vescico-ureterale, fase dopo la rimozione di un ostacolo","Se la vescica è molto distesa, la dilatazione dei reni si rivaluta dopo la minzione o il cateterismo","Un rene dilatato con febbre e brividi indica un'infezione a monte di un ostacolo: è un'urgenza che richiede drenaggio (nefrostomia o stent ureterale)","Una corticale sottile e un rene piccolo indicano danno cronico"],
 i:["Nella colica renale: valuta dolore con scala, somministra l'analgesia prescritta, controlla temperatura e diuresi, filtra le urine se richiesto per recuperare il calcolo","Segnala subito febbre, brividi, calo della diuresi o della pressione in un paziente con ostruzione nota","Prima dell'ecografia renale e vescicale chiede di non svuotare la vescica, se previsto dal protocollo"],
 e:["Diagnosticare un'idronefrosi bilaterale senza aver guardato la vescica","Considerare benigna una colica con febbre"],
 r:["rene-fisiologia","insufficienza-renale","eco-vescica","urine"]},
{id:"eco-aorta",a:"eco",s:"Aorta addominale",t:"Aneurisma dell'aorta addominale: screening e rottura",
 d:"L'aorta addominale si vede con la sonda convex sotto l'apofisi xifoide, davanti alla colonna e a sinistra della vena cava. Normalmente misura circa 2 cm; si parla di aneurisma quando il diametro supera 3 cm. L'ecografia è l'esame di primo livello per lo screening e il controllo nel tempo.",
 v:[["Normale","circa 2 cm, pareti regolari, si riduce leggermente verso la biforcazione"],["Ectasia","dilatazione modesta, sotto la soglia dell'aneurisma"],["Aneurisma","diametro superiore a 3 cm, spesso con trombo murale grigio lungo la parete"],["Soglia di riparazione","di solito 5,5 cm nell'uomo e circa 5 cm nella donna, o crescita rapida, o sintomi"],["Endoleak","dopo un'endoprotesi, flusso che continua a riempire la sacca aneurismatica: va controllato nel tempo"]],
 p:["La misura si prende in scansione trasversale, perpendicolare all'asse del vaso: se l'aorta è tortuosa, una misura obliqua sovrastima il diametro","Il trombo murale è grigio e il lume pervio nero: misurare solo il lume colorato sottostima l'aneurisma","Fattori di rischio: sesso maschile, età oltre 65 anni, fumo, ipertensione, familiarità","Più l'aneurisma è grande, più aumenta il rischio di rottura; i controlli si fanno più ravvicinati man mano che il diametro cresce","Rottura: dolore improvviso addominale o lombare, ipotensione e massa pulsante. In un paziente in shock con un aneurisma grande si presume la rottura; l'ecografia vede male l'ematoma retroperitoneale, quindi non deve ritardare la chirurgia"],
 i:["Nel sospetto di rottura: allerta immediata del team, due accessi venosi di grosso calibro, prove crociate ed emocomponenti pronti, monitoraggio continuo; i liquidi si danno secondo indicazione medica mantenendo una pressione bassa ma sufficiente (ipotensione permissiva)","Nella persona con aneurisma in sorveglianza: educa a smettere di fumare, a controllare la pressione e a recarsi subito in pronto soccorso in caso di dolore improvviso","Per l'esame programmato: digiuno di alcune ore per ridurre i gas intestinali"],
 e:["Riportare subito la pressione a valori normali con grandi volumi in una rottura","Rassicurare un paziente instabile perché l'ecografia «non mostra sangue»"],
 r:["shock","ipertensione","eco-fast","eco-vci"]},
{id:"eco-pocus",a:"eco",s:"Protocolli al letto",t:"Ecografia al punto di cura: FAST, eFAST, RUSH e approccio ABCD",
 d:"L'ecografia al punto di cura (POCUS) è eseguita al letto da chi assiste il paziente per rispondere a domande precise, con risposte del tipo sì o no, e integra l'esame clinico senza sostituirlo. I protocolli organizzano le scansioni in sequenze rapide e ripetibili.",
 v:[["FAST","nel trauma cerca liquido libero: spazio tra fegato e rene destro, intorno alla milza, pelvi dietro la vescica, pericardio"],["eFAST","aggiunge il torace: scivolamento pleurico per escludere il pneumotorace e basi per il versamento"],["RUSH","nello shock indifferenziato guarda la «pompa» (cuore, pericardio), il «serbatoio» (vena cava, liquido libero, polmone) e i «tubi» (aorta, vene profonde)"],["Approccio ABCD","segue la valutazione primaria: vie aeree, respiro (pneumotorace, linee B, versamento), circolo (cuore, cava, aorta, trombosi venosa, FAST) e, in alcuni protocolli, valutazioni neurologiche"],["Nell'arresto cardiaco","durante le brevi pause del massaggio permette di vedere se c'è attività contrattile e cause reversibili (tamponamento, pneumotorace), senza allungare le interruzioni"]],
 p:["Una FAST negativa non esclude una lesione: si ripete se il quadro cambia","Il liquido libero si raccoglie nelle zone declivi: in posizione supina lo spazio tra fegato e rene è il primo punto da controllare","L'ecografia toracica è più sensibile della radiografia in posizione supina per il pneumotorace","Ogni esame va registrato con ora, finestre esplorate e risultato"],
 i:["Prepara l'ecografo e la persona, aiuta con il posizionamento e documenta orari e risultati","Durante la rianimazione cronometra le pause: l'ecografia non deve prolungare l'interruzione delle compressioni oltre quanto previsto dalle linee guida","Nei contesti in cui è formato, esegue scansioni mirate (vescica, accessi venosi) secondo protocolli aziendali"],
 e:["Usare l'ecografia per ritardare un trattamento urgente","Ripetere a voce un «negativo» come se escludesse tutto"],
 r:["eco-fast","eco-vci","eco-polmone","trauma","shock","bls-acls"]},
{id:"eco-procedure",a:"eco",s:"Procedure ecoguidate",t:"Procedure ecoguidate: tecnica, asepsi e ruolo dell'infermiere",
 d:"L'ecografia rende più sicuri prelievi, drenaggi e posizionamenti di cateteri perché mostra il bersaglio, i vasi da evitare e il percorso dell'ago. Si distinguono la tecnica eco-assistita (si individua e si marca il punto, poi si procede senza sonda) e la guida in tempo reale (si segue l'ago sullo schermo).",
 v:[["Asse lungo (in-plane)","l'ago entra dal lato corto della sonda e si vede per intero, punta compresa"],["Asse corto (out-of-plane)","l'ago entra dal lato lungo e si vede come un punto bianco: bisogna inseguire la punta inclinando la sonda"],["Guida porta-ago","adattatore fissato alla sonda: lo schermo mostra la linea del percorso; più preciso in profondità ma meno libero"],["Ago-aspirato (FNAC)","ago sottile per prelevare cellule"],["Biopsia con ago tranciante","preleva un frustolo di tessuto per l'esame istologico"],["Paracentesi e toracentesi","drenaggio di liquido da addome o torace nel punto più sicuro individuato con l'ecografia"]],
 p:["Si sceglie il percorso più breve e sicuro, lontano da vasi e anse intestinali","L'ago si vede meglio quando attraversa liquido o tessuti scuri e quando è perpendicolare al fascio","Prima di procedure invasive si controllano coagulazione, piastrine e terapia anticoagulante o antiaggregante, secondo le soglie del protocollo","La sonda si usa con copri-sonda e gel sterili; la cute si disinfetta come per ogni procedura asettica"],
 i:["Verifica consenso informato, identità, digiuno se richiesto, esami della coagulazione e terapie in corso","Prepara il campo sterile, il copri-sonda, il gel sterile, aghi e contenitori per i campioni con etichette corrette","Dopo la procedura sorveglia parametri vitali, dolore, sito di puntura e segni di sanguinamento; dopo una toracentesi osserva respiro e saturazione, dopo una paracentesi abbondante la pressione","Pulisce e disinfetta la sonda secondo il livello richiesto dal tipo di procedura"],
 e:["Usare gel non sterile in una procedura invasiva","Scambiare il corpo dell'ago per la punta nell'asse corto"],
 r:["eco-accessi","consenso-informato","es-coagulazione","drenaggi","sterilizzazione"]}
);
if(typeof MNEMO!=="undefined")Object.assign(MNEMO,{
 "eco-aorta":[["«Due normale, tre aneurisma, cinque e mezzo si opera»","Aorta addominale circa 2 cm; sopra 3 cm aneurisma; riparazione di solito da 5,5 cm nell'uomo."],["Triade della rottura: dolore, ipotensione, massa pulsante","In un paziente in shock con aneurisma grande si presume la rottura."]],
 "eco-rene":[["«Prima la vescica, poi i reni»","Una vescica sovradistesa può dilatare i reni: si ricontrolla dopo averla svuotata."],["«Ostruito e febbrile = urgente»","Un rene dilatato con febbre va drenato subito."]],
 "eco-pocus":[["RUSH: pompa, serbatoio, tubi","Cuore e pericardio; cava, liquido libero e polmone; aorta e vene profonde."]],
 "eco-procedure":[["«In-plane vedi tutto, out-of-plane vedi un punto»","Nell'asse lungo l'ago si vede intero; nell'asse corto solo dove taglia il fascio."]],
 "eco-regolazioni":[["«Il sangue deve restare nero»","Se i vasi sono grigi il guadagno è troppo alto."]]
});

/* Enciclopedia — triage da protocolli di pronto soccorso (lotto 1: reazioni allergiche, stato mentale, respiro, ustioni, dolore toracico). Contenuti rielaborati con parole proprie a partire dalla struttura dei protocolli di triage a 5 livelli; nessun testo riprodotto. */
ENC.push(
{id:"tri-allergia",a:"emerg",s:"Triage: reazioni allergiche",t:"Reazione allergica e anafilassi: riconoscere la gravità",
 d:"Una reazione allergica va dal prurito localizzato allo shock anafilattico. Il triage deve riconoscere in fretta i segni che coinvolgono le vie aeree e la circolazione, perché sono quelli che portano a morte in pochi minuti.",
 v:[["Livello 1 (critico)","difficoltà respiratoria grave, paziente incosciente, ipotensione, gonfiore di lingua o gola, saturazione sotto il 90% anche con ossigeno"],["Livello 2 (emergente)","gonfiore orale, stridore o respiro sibilante, voce rauca, parla a frasi brevi, difficoltà a deglutire, orticaria diffusa, anafilassi precedente"],["Livello 3 (urgente)","sintomi che persistono dopo antistaminico o adrenalina, gonfiore lieve, nausea, vomito o diarrea persistenti, orticaria estesa"],["Livello 4-5 (non critico)","contatto cutaneo con l'allergene, orticaria localizzata, rash persistente senza problemi respiratori"]],
 p:["Il paziente con segni respiratori o circolatori va considerato anafilassi finché non si dimostra il contrario","Il sintomo che fa salire il livello è quasi sempre il respiro: gonfiore della gola, voce rauca, stridore","Un sintomo cutaneo isolato può precedere un peggioramento: il triage va rivalutato a intervalli brevi","L'adrenalina intramuscolo è il trattamento di prima scelta nell'anafilassi, senza aspettare altri farmaci","Anche dopo il miglioramento il paziente va osservato, perché i sintomi possono ritornare"],
 i:["Valuta subito vie aeree, respiro e circolo, poi segnala al medico","Prepara l'adrenalina e il materiale per la via aerea; chiedi se il paziente ha già ricevuto farmaci","Fai sdraiare il paziente con le gambe sollevate se è ipoteso, seduto se ha difficoltà respiratorie","Annota ora di inizio, farmaci dati, dosi e risposta"],
 e:["Considerare lieve un gonfiore della gola con voce rauca solo perché la pressione è normale","Aspettare la comparsa di tutti i sintomi prima di trattare"],
 r:["triage","maxiemergenza"]},
{id:"tri-stato-mentale",a:"emerg",s:"Triage: stato di coscienza",t:"Alterazione dello stato mentale: il segno che non va ignorato",
 d:"Confusione, sonnolenza, agitazione o perdita di coscienza hanno cause molto diverse: ipoglicemia, intossicazione, ictus, trauma cranico, infezione, sepsi, crisi epilettica. Il triage non deve diagnosticare la causa, ma riconoscere subito chi rischia.",
 v:[["Livello 1","apnea o grave difficoltà respiratoria, paziente incosciente, pallido e sudato, crisi epilettica prolungata, arresto cardiaco"],["Livello 2","alterazione dello stato mentale, intossicazione o overdose, pericolo per sé o per gli altri, cefalea intensa con vomito a getto, segni di ictus con esordio entro 2 ore, glicemia alterata"],["Livello 3","paziente sveglio e orientato con cefalea, febbre senza rigidità del collo, trauma cranico recente, crisi tonico-clonica che si è risolta, agitazione lieve"],["Livello 4-5","sonnolenza dopo il sonno o la stanchezza, perdita di coscienza breve e già risolta, intossicazione lieve senza segni neurologici"]],
 p:["Ogni alterazione della coscienza va trattata come sintomo: chiedi sempre glicemia, farmaci assunti, alcol o sostanze, trauma","Un trauma alla testa in un paziente che peggiora nel tempo è un'emergenza, anche se all'inizio era sveglio","Il segno di ictus si cerca in modo strutturato: viso asimmetrico, forza nelle braccia, parola","Un paziente con cefalea, febbre e collo rigido va trattato come possibile meningite fino a prova contraria","Con la scala di coma si registra il valore prima di ogni intervento, così il cambiamento si vede"],
 i:["Controlla glicemia capillare, parametri vitali, saturazione e temperatura","Proteggi le vie aeree: posiziona il paziente in posizione laterale di sicurezza se non risponde","Chiedi a chi accompagna cosa è successo, da quanto tempo e quali farmaci o sostanze sono stati assunti","Segnala subito ogni peggioramento e annotalo con l'ora"],
 e:["Attribuire la confusione all'età o all'alcol senza misurare la glicemia","Lasciare solo un paziente agitato o sonnolento"],
 r:["triage","maxiemergenza"]},
{id:"tri-respiro",a:"emerg",s:"Triage: respiro",t:"Problemi respiratori: segni di allarme al triage",
 d:"La difficoltà respiratoria è uno dei motivi di accesso più pericolosi. Il triage valuta frequenza, fatica, parole pronunciate, colore della pelle e saturazione. Il dato più affidabile è l'insieme di questi segni, non uno solo.",
 v:[["Livello 1","apnea, grave difficoltà respiratoria, paziente che non riesce a parlare, cianosi centrale, saturazione sotto il 90% con ossigeno"],["Livello 2","ostruzione delle vie aeree, sensazione di soffocamento, sibili o stridore gravi, parla a frasi brevi, pallore o unghie cianotiche, dolore toracico, criteri SIRS"],["Livello 3","dolore che aumenta con il respiro, tosse stretta, sibili lievi a riposo, respiro che peggiora da meno di 2 ore, sospetto di corpo estraneo inalato"],["Livello 4-5","parla a frasi intere, febbre lieve senza difficoltà, saturazione sopra il 95% in aria, iperventilazione con formicolio senza segni organici"]],
 p:["La saturazione va letta insieme alla circolazione: con estremità fredde può essere falsamente bassa, con monossido di carbonio falsamente normale","Nei pazienti con BPCO l'obiettivo di saturazione è più basso, per il rischio di accumulo di anidride carbonica: segui il protocollo locale","Una tosse con espettorato rosato e schiumoso può indicare edema polmonare e va trattata come urgenza","Il paziente che parla a frasi brevi o non riesce a parlare ha un respiro insufficiente, indipendentemente dal valore della saturazione","L'iperventilazione con formicolio va sempre distinta da una difficoltà respiratoria reale, ma va comunque misurata"],
 i:["Metti il paziente seduto e aiutalo a trovare la posizione più comoda","Somministra ossigeno secondo protocollo e misura la saturazione dopo l'inizio","Controlla frequenza respiratoria, uso dei muscoli accessori e colore della pelle","Chiedi subito se ci sono state cause scatenanti: allergie, trauma, viaggi, farmaci"],
 e:["Attribuire la dispnea all'ansia senza aver misurato saturazione e frequenza","Somministrare ossigeno ad alta concentrazione a un paziente con BPCO senza protocollo"],
 r:["triage","maxiemergenza"]},
{id:"tri-ustioni",a:"emerg",s:"Triage: ustioni",t:"Ustioni: estensione, profondità e segni di gravità",
 d:"Il triage delle ustioni valuta la causa, la sede, l'estensione e la profondità. Le ustioni che coinvolgono le vie aeree, il viso, il collo o un arto possono peggiorare rapidamente, anche se la superficie sembra piccola.",
 v:[["Livello 1-2","compromissione respiratoria, ustioni elettriche, chimiche o da radiazioni, ustioni circonferenziali di collo o arto con polso distale assente, ustione estesa bianca e indolore, ustione con alterazione dello stato mentale"],["Livello 3","ustione sopra un'articolazione, vesciche su viso o collo, ustione di più di 2,5 cm su viso, occhi, orecchie, mani, piedi o genitali, dolore intenso"],["Livello 4-5","dolore moderato o lieve, vesciche piccole e aperte, ustione piccola, immunizzazione antitetanica recente"]],
 p:["La regola del nove stima l'estensione negli adulti: ogni arto vale circa il 9%, la testa il 9%, il tronco davanti e dietro il 18% ciascuno","Un'ustione bianca e indolore è più profonda di quanto sembra, perché le terminazioni nervose sono distrutte","Il tetano va verificato in ogni ustione: l'ultima dose di richiamo oltre i 5 anni o lo stato vaccinale sconosciuto cambiano il trattamento","L'ustione elettrica può danneggiare i tessuti profondi molto più di quanto si veda in superficie","Il fumo con peli del naso o del viso bruciati fa sospettare un danno alle vie aeree"],
 i:["Valuta le vie aeree e il respiro prima di tutto: segni di inalazione di fumo, voce alterata, peli bruciati","Raffredda la parte ustionata con acqua corrente per il tempo indicato dal protocollo, se è passato poco tempo","Rimuovi anelli, orologi e vestiti attorno alla zona prima che si gonfi","Copri con un telo pulito e non applicare creme o ghiaccio"],
 e:["Considerare superficiale un'ustione bianca solo perché non fa male","Usare ghiaccio o creme sulla lesione"],
 r:["triage","maxiemergenza"]},
{id:"tri-dolore-toracico",a:"emerg",s:"Triage: dolore toracico",t:"Dolore toracico: distinguere l'urgenza cardiaca",
 d:"Il dolore al petto può essere un infarto, un'embolia, un'aorta che si dissecca o un problema gastrico o muscolare. Il triage non decide la causa: deve riconoscere subito i pazienti che hanno bisogno di un ECG entro pochi minuti.",
 v:[["Livello 1","arresto cardiaco, ipotensione, cianosi centrale, scompenso del LVAD"],["Livello 2","dolore che si irradia al collo, alla mandibola, alla schiena o al braccio; sudorazione fredda e pelle pallida; nausea; dispnea; età oltre 35 anni con palpitazioni; dolore severo a riposo; dolore che persiste dopo tre dosi di nitroglicerina"],["Livello 3","dolore moderato con parametri stabili, palpitazioni in soggetto giovane, dolore con lo sforzo, fattori di rischio cardiovascolare importanti, dolore e gonfiore di una gamba"],["Livello 4-5","dolore che aumenta con il respiro o la pressione sul torace, febbre e tosse, dolore cronico noto"]],
 p:["Nel dolore toracico l'ECG va eseguito e letto entro pochi minuti dall'arrivo: il tempo è la variabile più importante","Le donne, gli anziani e i diabetici possono avere sintomi atipici: nausea, dispnea o stanchezza senza dolore tipico","Un dolore che peggiora con il respiro o il movimento è più spesso di origine muscolare o pleurica, ma va comunque valutato","Il sintomo va sempre descritto con la sede, l'intensità, la durata, l'irradiazione e ciò che lo migliora o lo peggiora","L'aspirina va somministrata secondo protocollo, dopo aver escluso controindicazioni"],
 i:["Fai sdraiare il paziente, monitorizza parametri e ritmo, misura la saturazione","Procura subito un ECG a 12 derivazioni e portalo al medico","Chiedi allergie, farmaci (in particolare anticoagulanti e farmaci per l'erezione), storia cardiaca e ultimo pasto","Non lasciare il paziente da solo e rivalutalo a intervalli brevi"],
 e:["Attribuire il dolore al reflusso senza ECG in un paziente con fattori di rischio","Far camminare o salire le scale un paziente con dolore toracico in corso"],
 r:["triage","maxiemergenza"]}
);
